// T-slot nut for aluminium extrusion
// Print orientation: flange down on the XY plane, neck building up (+Z)

// ---------------- Dimensions (mm) ----------------
nut_length     = 10;    // length along X
flange_width   = 12;    // bottom flange width (Y)
flange_thick   = 2.5;   // flange thickness, z = 0 .. 2.5
neck_width     = 6;     // neck width (Y), centred
total_height   = 5.5;   // top of neck (Z)
hole_d         = 3.4;   // vertical screw clearance hole diameter

eps            = 0.5;   // cutter overshoot past faces
$fn            = 64;    // facet count for round features

// ---------------- Model ----------------
difference() {
    union() {
        // Bottom flange
        translate([-nut_length/2, -flange_width/2, 0])
            cube([nut_length, flange_width, flange_thick]);

        // Centred neck (overlaps flange slightly to fuse cleanly)
        translate([-nut_length/2, -neck_width/2, flange_thick - 0.01])
            cube([nut_length, neck_width, total_height - flange_thick + 0.01]);
    }

    // Vertical screw hole through the centre
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = total_height + 2*eps, $fn = $fn);
}
