```openscad
// T-shaped extrusion nut - slides into the slot of an aluminium profile.
// Print orientation: flange on the bed (z = 0), neck pointing up (+Z).
//
// NOTE: This part is a screw slide, not a wrench. It is not designed to
// bear a heavy downward load on the screw head; use a spanner for that.

$fn = 64;

// ---- Dimensions (mm) ----
flange_w      = 12;   // flange width (Y)
flange_t      = 2.5;  // flange thickness (Z)
neck_w        = 6;    // neck width (Y)
neck_h        = 5.5;  // neck top height (Z), measured from the bed
screw_d       = 3.4;  // central screw hole diameter
profile_len   = 10;   // part length along X
eps           = 0.5;  // cutter overshoot past faces

// ---- Model ----
difference() {
    union() {
        // Bottom flange: y = -6 .. 6, z = 0 .. 2.5
        translate([-profile_len/2, -flange_w/2, 0])
            cube([profile_len, flange_w, flange_t]);

        // Centred neck: y = -3 .. 3, z = 2.5 .. 8 (10 mm overlap into the flange)
        translate([-profile_len/2, -neck_w/2, flange_t - 0.01])
            cube([profile_len, neck_w, neck_h + 0.01]);
    }

    // Vertical screw hole through the full height
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_h + flange_t + 2*eps);
}
```

