```openscad
// T-shaped extrusion nut - slides into the slot of an aluminium profile.
// Print orientation: flange on the bed (z = 0), neck pointing up (+Z).
//
// NOTE: This part is a screw slide, not a screw. It has a through-hole
// for a 4.5 mm screw or rod and does not have a threaded bore.

// ---------------- Parameters ----------------
flange_w     = 14;   // flange width (Y)
flange_t     = 2.5;  // flange thickness (Z)
neck_w       = 7;    // neck width (Y)
neck_h       = 3;    // neck height above flange (Z)
length_x     = 12;   // part length along X
hole_d       = 4.5;  // central screw through-hole diameter
eps          = 0.5;  // cutter overshoot past faces
$fn          = 64;   // curve resolution

// Combined heights
flange_z = flange_t;
total_h  = flange_z + neck_h;

// ---------------- Model ----------------
difference() {
    union() {
        // Bottom flange: y = -flange_w/2 .. flange_w/2, z = 0 .. flange_t
        translate([-length_x/2, -flange_w/2, 0])
            cube([length_x, flange_w, flange_t]);

        // Centred neck: y = -neck_w/2 .. neck_w/2, z = flange_t .. total_h
        translate([-length_x/2, -neck_w/2, flange_z])
            cube([length_x, neck_w, neck_h]);
    }

    // Vertical through-hole, centred on the part
    translate([-length_x/2 - eps, 0, -eps])
        cylinder(d = hole_d, h = total_h + 2*eps);
}
