// Anti-vibration foot for benchtop instrument
// Print orientation: base on bed (z = 0), top facing up

// ---------- Parameters ----------
bottom_d      = 50;    // bottom diameter (mm)
top_d         = 42;    // top diameter (mm)
height        = 12;    // frustum height (mm)
recess_d      = 44;    // rubber pad recess diameter (mm)
recess_depth  = 3;     // rubber pad recess depth (mm)
screw_d       = 4.5;   // central screw hole diameter (mm)
eps           = 0.5;   // cutter overshoot past faces (mm)

$fn = 128;

// ---------- Model ----------
difference() {
    // Frustum standing on z = 0, centred on Z axis
    cylinder(d = bottom_d, h = height, $fn = 128);

    // Round recess in bottom face for rubber pad
    translate([0, 0, -eps])
        cylinder(d = recess_d, h = recess_depth + 2 * eps, $fn = 128);

    // Through hole for screw along axis
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = height + 2 * eps, $fn = 64);
}
