    cylinder(h = height, d1 = base_d, d2 = top_d);

    // Recess in the bottom face for the rubber pad
    translate([0, 0, -eps])
        cylinder(h = recess_h + eps, d = recess_d);

    // Central screw hole, through the full height
    translate([0, 0, -eps])
        cylinder(h = height + 2 * eps, d = screw_d);
}
