        // Bowl: lower half of hollow sphere
        translate([0, 0, bowl_z0])
            sphere(r = bowl_r, $fn = 192);
        translate([0, 0, bowl_z0 - wall])
            sphere(r = bowl_r - wall, $fn = 192);

        // Handle: flat plate, top face flush with rim (z = 9 to 12)
        translate([handle_x0, -handle_w / 2, bowl_z0 - wall - eps])
            cube([handle_x1 - handle_x0, handle_w, handle_t + 2 * eps]);
    }

