// Ring weight for flask neck in a water bath
// Torus lying flat on the bed, swept around the Z axis
// Units: mm

// ---------------- Parameters ----------------
tube_d      = 16;            // diameter of the round cross-section
tube_r      = tube_d / 2;    // radius of the cross-section (8 mm)
ring_r      = 25;            // radius of the circle the section centre follows
outer_d     = 2 * (ring_r + tube_r); // overall diameter = 66 mm (reference)
inner_d     = 2 * (ring_r - tube_r); // inner hole diameter = 34 mm (reference)
mid_z       = tube_r;        // middle plane height (8 mm), so base touches z = 0

// Resolution
fn_sweep    = 128;           // segments around the Z axis
fn_section  = 64;            // segments around the cross-section circle

// ---------------- Model ----------------
translate([0, 0, mid_z])
    rotate_extrude($fn = fn_sweep)
