// Tapered riser block for beaker - solid square frustum with a square pocket in the top face
// Print orientation: base on the bed (z = 0), top face at z = 30, centred on origin in X and Y

// ---------------- Parameters ----------------
bottom_size   = 80;   // length of the bottom square side (mm)
top_size      = 50;   // length of the top square side (mm)
height        = 30;   // height of the frustum (mm)
pocket_size   = 40;   // length of the square pocket side (mm)
pocket_depth  = 5;    // depth of the pocket cut into the top face (mm)
eps           = 0.5;  // overshoot for clean boolean cuts (mm)
$fn           = 64;   // curve resolution (not used here, set per the rules)

// ---------------- Derived ----------------
// Side length of the square at height h, linearly interpolated between bottom and top
function side(h) = bottom_size + (top_size - bottom_size) * h / height;
// Area of the square at height h
function area(h) = side(h) * side(h);

// ---------------- Model ----------------
difference() {
    // Frustum body, built in layers 1 mm thick from z = 0 to z = height
    for (i = [0 : height])
        translate([0, 0, i])
            cube([side(i), side(i), 1]);

    // Square pocket, centred on the top face and extended eps above it to avoid coplanar faces
    translate([-pocket_size / 2, -pocket_size / 2, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
