// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 4;     // specimen thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 15;    // transition section length (X)
eps            = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
head_start = -total_length / 2 + grip_length;        // -45
gauge_x0   = head_start + grip_length + transition_len; // 30
head_end   = total_length / 2 - grip_length;          // 45

// ---------- Model ----------
difference() {
    // Outer shape: two grip blocks with linearly widened transitions
    union() {
        // Left grip
        translate([head_start - eps, -grip_width / 2, 0])
            cube([grip_length + 2 * eps, grip_width, thickness]);

        // Right grip
        translate([head_end - eps, -grip_width / 2, 0])
            cube([grip_length + 2 * eps, grip_width, thickness]);

        // Transitions (width changes linearly from 15 to 8)
        for (sx = [-1, 1])
            translate([sx > 0 ? gauge_x0 - transition_len - eps : head_start - eps,
                       -grip_width / 2, 0])
                linear_extrude(thickness)
                    polygon([[-transition_len, -grip_width / 2],
                             [-transition_len, grip_width / 2],
                             [sx * (transition_len - 0.01), gauge_width / 2],
                             [sx * (transition_len - 0.01), -gauge_width / 2]]);
    }

    // Central gauge section (constant width 8)
    translate([gauge_x0, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, thickness]);
}
