transition_end_x = gauge_start_x + transition_len; // -7.5

module specimen() {
    difference() {
        // Outer shape: grip -> transition -> gauge -> transition -> grip
        union() {
            for (sx = [-grip_start_x, grip_start_x])
                translate([sx, 0, 0])
                    cube([grip_length, grip_width, thickness]);
            for (tx = [-transition_end_x, transition_end_x])
                translate([tx, 0, 0])
                    cube([transition_len, grip_width - (grip_width - gauge_width) * (transition_len - (tx - (gauge_start_x + transition_len/2))), thickness]);
            translate([gauge_start_x, 0, 0])
                cube([gauge_length, gauge_width, thickness]);
        }
        // Central hole through gauge section
        translate([gauge_start_x + gauge_length/2, 0, -1])
            cube([gauge_length, 4, thickness + 2]);
    }
}

specimen();
