thickness      = 6;    // overall wheel thickness (Z)
rim_od         = 80;   // rim outer diameter
rim_width      = 4;    // rim radial width
hub_d          = 16;   // hub outer diameter
axle_d         = 8;    // axle hole diameter
spoke_count    = 4;    // number of spokes
spoke_width    = 5;    // spoke width
eps            = 0.5;  // cut overlap past faces
$fn            = 128;  // smoothness of curved shapes

// ---------- Derived ----------
rim_r       = rim_od / 2;          // 40
rim_inner_r = rim_r - rim_width;   // 36
hub_r       = hub_d / 2;           // 8
// spokes span from hub centre region into the rim for solid overlap
spoke_start = hub_r / 2;
spoke_len   = (rim_inner_r + rim_width / 2) - spoke_start;

// ---------- Model ----------
difference() {
    union() {
        // Outer rim
        difference() {
            cylinder(h = thickness, r = rim_r);
            translate([0, 0, -eps])
                cylinder(h = thickness + 2 * eps, r = rim_inner_r);
        }

        // Hub
        cylinder(h = thickness, r = hub_r);

        // Spokes, first along +X
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([spoke_start, -spoke_width / 2, 0])
                    cube([spoke_len, spoke_width, thickness]);
    }

    // Axle hole through centre
    translate([0, 0, -eps])
        cylinder(h = thickness + 2 * eps, d = axle_d);
}
