```openscad
// T-shaped extrusion nut - slides into the slot of an aluminium profile.
// Print orientation: flange on the bed (z = 0), neck pointing up (+Z).
//
// NOTE: This part is a screw slide, not a bearing. It is not designed to
// support axial loads or high speeds. Use with a coarse screw and at low
// speed. Do not use with dryfite or other low-friction liners in the slot.
//
// A 4.5 mm screw hole runs vertically through the centre of the part.

$fn = 64;

// ---- Dimensions (mm) ----
t_flange   = 3;     // flange thickness (z = 0 to 3)
w_flange   = 10;    // flange width (Y)
w_neck     = 7;     // neck width (Y), centred on flange
h_neck     = 3;     // neck height above flange (z = 3 to 6)
l_profile  = 12;    // part length along X, centred on origin
screw      = 4.5;   // central screw hole diameter

// ---- Model ----
union() {
    // Bottom flange: y = -w_flange/2 .. w_flange/2, z = 0 .. t_flange
    translate([-l_profile/2, -w_flange/2, 0])
        cube([l_profile, w_flange, t_flange]);

    // Neck: y = -w_neck/2 .. w_neck/2, z = t_flange .. t_flange + h_neck
    translate([-l_profile/2, -w_neck/2, t_flange])
        cube([l_profile, w_neck, h_neck]);
}

// Central screw hole, through the full height
translate([0, 0, -1])
    cylinder(d = screw, h = t_flange + h_neck + 2);
