```openscad
// Flat dial ring with radial tick marks for a rotary stage
// Print orientation: flat on bed, tick marks facing up

// ---- Dimensions (mm) ----
outer_d      = 60;    // outer diameter of annulus
inner_d      = 44;    // inner diameter of annulus
thickness    = 3;     // ring thickness (Z)
tick_count   = 24;    // number of tick marks
tick_width   = 1.2;   // groove width
tick_depth   = 1.5;   // groove depth from top face
tick_length  = 3;     // groove extends inward from outer edge
eps          = 0.5;   // cutter overshoot past faces

$fn = 128;

// ---- Model ----
difference() {
    // Annulus body, centred in XY, resting on z = 0
    cylinder(d = outer_d, h = thickness);

    // Central bore
    translate([0, 0, -eps])
        cylinder(d = inner_d, h = thickness + 2 * eps);

    // Radial tick grooves, first on +X axis
    for (i = [0 : tick_count - 1]) {
        rotate([0, 0, i * 360 / tick_count])
            translate([outer_d / 2 - tick_length, 0, thickness - tick_depth])
                cube([tick_width, outer_d / 2 + 1, tick_depth + eps]);
    }
}
