```openscad
// Flat dial ring with radial tick marks for a rotary stage
// Print orientation: flat on bed, top face (with ticks) facing up

$fn = 128;

// ---- Ring dimensions ----
outer_d   = 60;    // outer diameter of ring
inner_d   = 44;    // inner (bore) diameter of ring
ring_t    = 3;     // ring thickness (Z)

// ---- Tick mark dimensions ----
tick_count = 24;   // number of evenly spaced ticks
tick_w     = 1.2;  // groove width
tick_depth = 1.5;  // groove depth from top face
tick_len   = 3;    // radial length, measured inward from outer edge

// ---- Helpers ----
eps = 0.5;         // overshoot for clean boolean cuts
outer_r = outer_d / 2;
inner_r = inner_d / 2;

difference() {
    // Annulus body
    difference() {
        cylinder(h = ring_t, r = outer_r);
        translate([0, 0, -eps])
            cylinder(h = ring_t + 2 * eps, r = inner_r);
    }

    // Radial tick grooves, first one on +X axis
    for (i = [0 : tick_count - 1]) {
        rotate([0, 0, i * 360 / tick_count])
            translate([outer_r - tick_len, -tick_w / 2, ring_t - tick_depth])
                cube([tick_len + eps, tick_w, tick_depth + eps]);
    }
}
