// Stiffened cover panel: flat plate with 4 longitudinal ribs
// Units: mm. Print orientation: plate on bed (z = 0), ribs build upward.

// ---------- Parameters ----------
plate_len   = 120;   // plate length along X
plate_wid   = 60;    // plate width along Y
plate_thk   = 2;     // plate thickness (z = 0 to 2)

rib_thk     = 3;     // rib thickness along X
rib_h       = 6;     // rib height above plate (z = 2 to 8)
rib_count   = 4;     // number of ribs
rib_pitch   = 24;    // centre-to-centre spacing of ribs
rib_overrun = 0.5;   // extra rib length past plate ends for clean union

$fn = 64;

// ---------- Derived ----------
plate_x0 = -plate_len / 2;        // plate start in X
plate_x1 = plate_len / 2;         // plate end in X
rib_z0   = plate_thk;             // rib base height
rib_x0   = plate_x0 - rib_overrun; // rib start (overruns plate)
rib_x1   = plate_x1 + rib_overrun; // rib end (overruns plate)

// Check: 4 ribs at 24 mm pitch leave 5 equal end parts (24 mm each)
assert(abs(plate_len - (rib_count * rib_pitch + (rib_count + 1) * rib_pitch)) < 0.001,
       "Rib layout does not divide the plate into equal parts.");

// ---------- Model ----------
union() {
    // Flat plate
    translate([plate_x0, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running full width along Y
    for (i = [0 : rib_count - 1]) {
        translate([
            plate_x0 + rib_pitch * i - rib_thk / 2,
            -plate_wid / 2,
            rib_z0
        ])
            cube([rib_thk, plate_wid, rib_h]);
    }
}
