            cylinder(r = bowl_r, h = bowl_z + 0.01, $fn = 128);   // outer
        translate([0, 0, bowl_z + wall])
            cylinder(r = bowl_r - wall, h = bowl_z - wall + 0.01, $fn = 128); // inner

        // Handle: flat plate, top face flush with rim (z = 11..15)
        translate([handle_x0, -handle_w / 2, bowl_z - handle_t])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }

    // Cut a small pocket under the rim so the handle fuses into the bowl
    translate([handle_x0 - eps, -handle_w / 2 - eps, bowl_z - handle_t - eps])
        cube([handle_x1 - handle_x0 + 2 * eps, handle_w + 2 * eps, handle_t + 2 * eps]);
}
