// Powder measuring scoop: hemispherical bowl with a flat handle
// Print orientation: bowl opening up, bottom of bowl touching bed at z = 0

$fn = 96;

// ---- Bowl ----
bowl_r_outer = 15;      // outer radius of bowl sphere
bowl_wall    = 1.5;     // wall thickness
bowl_r_inner = bowl_r_outer - bowl_wall; // inner radius (13.5)
bowl_cz      = 15;      // Z of sphere centre (= rim height)

// ---- Handle ----
handle_x0    = 13.5;    // handle start (X)
handle_x1    = 95;      // handle end (X)
handle_w     = 8;       // handle width (Y)
handle_t     = 4;       // handle thickness (Z)
handle_ztop  = 15;      // top face of handle, flush with rim

eps = 0.5;              // overlap for clean cuts

module bowl() {
    difference() {
        translate([0, 0, bowl_cz]) sphere(r = bowl_r_outer);
        // hollow interior
        translate([0, 0, bowl_cz]) sphere(r = bowl_r_inner);
        // remove upper half
        translate([-(bowl_r_outer + eps), -(bowl_r_outer + eps), bowl_cz])
            cube([2 * (bowl_r_outer + eps), 2 * (bowl_r_outer + eps), bowl_r_outer + eps]);
    }
}

module handle() {
    translate([handle_x0, -handle_w / 2, handle_ztop - handle_t])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
}

difference() {
    union() {
        bowl();
        handle();
    }
    // keep bowl cavity clear of any handle material
    translate([0, 0, bowl_cz]) sphere(r = bowl_r_inner);
}
