        translate([-plate_l / 2, -plate_w / 2, 0])
            cube([plate_l, plate_w, plate_t]);

        // Knuckles on 1st, 3rd, 5th segments
        for (i = [0 : knuckle_n - 1]) {
            if ((i + 1) % 2 == 0) continue; // even segments skipped
            translate([knuckle_x0 + i * knuckle_p - knuckle_h,
                       plate_w / 2,
                       knuckle_z])
                cylinder(d = knuckle_d, h = knuckle_p + 2 * knuckle_h);
        }
    }

    // Pin holes through every knuckle along X
    for (i = [0 : knuckle_n - 1]) {
        if ((i + 1) % 2 == 0) continue;
        translate([knuckle_x0 + i * knuckle_p - knuckle_h - 1,
                   plate_w / 2,
                   knuckle_z])
            cylinder(d = pin_d, h = knuckle_p + 2 * knuckle_h + 2);
    }
}
