// Tapered riser block for beaker setting
// Print orientation: base on bed (z = 0), top face at z = 25

// ---------- Parameters ----------
base_size      = 100;   // bottom square side (mm)
top_size       = 70;    // top square side (mm)
height         = 25;    // block height (mm)
pocket_size    = 60;    // square pocket side (mm)
pocket_depth   = 5;     // square pocket depth (mm)
eps            = 0.5;   // cutter overshoot past faces (mm)
$fn            = 64;    // curve resolution (no curved shapes, set per rules)

// ---------- Derived ----------
// Linear taper rate per mm height
taper = (base_size - top_size) / (2 * height);

// ---------- Model ----------
difference() {
    // Main frustum body, centred in X/Y, resting on z = 0
    translate([-base_size / 2, -base_size / 2, 0])
        linear_extrude(height = height)
            polygon([[-base_size / 2, -base_size / 2],
                     [-base_size / 2, base_size / 2],
                     [base_size / 2, base_size / 2],
                     [base_size / 2, -base_size / 2]]);

    // Square pocket cut into the top face, centred
    translate([-pocket_size / 2, -pocket_size / 2, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
