// Tapered riser block for beaker - solid square frustum with a square pocket in the top face
// Units: mm. Print orientation: base on bed (z = 0), centred on origin in X and Y.

// ---------------- Parameters ----------------
bottom_size   = 100;   // length of bottom square side (X and Y)
top_size      = 70;    // length of top square side (X and Y)
height        = 25;    // overall height of frustum
pocket_size   = 60;    // length of square pocket side (X and Y)
pocket_depth  = 5;     // depth of pocket from top face
eps           = 0.5;   // overshoot for clean boolean cuts

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Square frustum: hull of bottom and top squares, edges parallel to X/Y
    hull() {
        translate([-bottom_size / 2, -bottom_size / 2, 0])
            cube([bottom_size, bottom_size, height]);

        translate([-top_size / 2, -top_size / 2, height])
            cube([top_size, top_size, height]);
    }

    // Square pocket centred on top face, open upward
    translate([-pocket_size / 2, -pocket_size / 2, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
