// Print orientation: base on bed (z = 0), builds upward

$fn = 64;

// ---------- Dimensions ----------
base_size    = 100;  // bottom square side (mm)
top_size     = 70;   // top square side (mm)
block_height = 25;   // overall height (mm)

pocket_size  = 60;   // square pocket side (mm)
pocket_depth = 5;    // pocket depth from top face (mm)

eps          = 0.5;  // overshoot for clean boolean cuts (mm)

// ---------- Model ----------
difference() {
    // Solid square frustum, flat sloping sides
    hull() {
        translate([-base_size/2, -base_size/2, 0])
            cube([base_size, base_size, 0.01]);
        translate([-top_size/2, -top_size/2, block_height - 0.01])
            cube([top_size, top_size, 0.01]);
    }

    // Square pocket cut into top face
    translate([-pocket_size/2, -pocket_size/2, block_height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
