overcut = 0.5;        // extension of cutting tools past faces

module handle_body() {
    union() {
        // Posts (extended slightly into the bar so they fuse)
        for (sx = [-1, 1])
            translate([sx * post_spacing / 2, 0, 0])
                cylinder(d = post_d, h = post_h + eps);

        // Bar on top of posts
        translate([-bar_len / 2, -bar_w / 2, post_h])
            cube([bar_len, bar_w, bar_t]);
    }
}

difference() {
    handle_body();

    // Screw holes up each post axis from the bottom face
    for (sx = [-1, 1])
        translate([sx * post_spacing / 2, 0, -overcut])
            cylinder(d = hole_d, h = hole_depth + overcut);
}
