            translate([s > 0 ? total_length / 2 - grip_l : -total_length / 2, -grip_w / 2, 0])
                cube([grip_l, grip_w, specimen_t]);
        // Gauge section
        translate([mid_x - gauge_l / 2, -gauge_w / 2, 0])
            cube([gauge_l, gauge_w, specimen_t]);
        // Transition sections (width changes linearly from 15 to 8 mm)
        for (s = [-1, 1])
            translate([s > 0 ? total_length / 2 - grip_l - trans_l : -total_length / 2, -grip_w / 2, 0])
                linear_extrude(specimen_t)
                    polygon([[-trans_l, s * (grip_w - gauge_w) / 2],
                             [trans_l, s * (grip_w - gauge_w) / 2]]);
    }
    // Cut a small notch at each end to avoid coplanar faces
    for (x = [-total_length / 2 + 1, total_length / 2 - 1])
        translate([x, -1, 0.01])
            cube([2, 2, 0.02]);
