        // Transitions (width changes linearly from 20 to 6)
        for (sx = [-1, 1])
            translate([sx > 0 ? gauge_x0 - eps : head_start - eps,
                       -grip_width / 2, 0])
                linear_extrude(thickness)
                    polygon([[-1, grip_width], [sx * (transition_len - eps),
                                         (grip_width - gauge_width) * sx / 2],
                            [transition_len - eps, (grip_width - gauge_width) * sx / 2]]);
    }

    // Central gauge section (constant width 6)
    translate([gauge_x0, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, thickness]);
}
