// ---------- Parameters ----------
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // transition section length (X)

// Derived
grip_x0        = -total_length/2 + grip_length + transition_len;  // left grip start
x_mid          = grip_x0 + grip_length + transition_len + gauge_length;  // gauge centre

// ---------- Model ----------
difference() {
    union() {
        // Left grip
        translate([grip_x0, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([x_mid - gauge_length/2, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right grip
        translate([x_mid + gauge_length + transition_len, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            x1 = s > 0 ? x_mid - gauge_length : grip_x0;
            x2 = x1 + transition_len;
            w1 = grip_width;
            w2 = gauge_width;
            translate([x1, -w1/2, 0])
                linear_extrude(thickness)
                    polygon([[x1, -w1/2], [x1, w1/2], [x2, w2/2], [x2, -w2/2]]);
        }
    }

    // Small cutouts along X to avoid coplanar faces
    for (x = [grip_x0 + grip_length, x_mid - gauge_length/2, x_mid + gauge_length + transition_len])
