neck_w     = 7;    // neck width (Y), centred on flange
neck_h     = 3;    // neck height above flange (z = 3 to 6)
profile_l  = 10;   // part length along X, centred on origin
screw_d    = 4.5;  // central screw hole diameter

eps        = 0.5;  // cutter overshoot past faces

// ---- Model ----
difference() {
    union() {
        // Bottom flange: full width, centred in X and Y
        translate([-profile_l/2, -flange_w/2, 0])
            cube([profile_l, flange_w, flange_t]);

        // Neck: centred on flange in X and Y, rises to z = flange_t + neck_h
        translate([-neck_w/2, -neck_w/2, flange_t])
            cube([neck_w, neck_w, neck_h]);
    }

    // Central screw hole, through the entire part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = flange_t + neck_h + 2*eps);
}
