// T-shaped extrusion nut - slides into the slot of an aluminium profile.
// Print orientation: flange on the bed (z = 0), neck pointing up (+Z).
//
// NOTE: This part is a screw slide, not a bearing. It is not designed to
// support axial loads or high speeds. Use with a coarse screw in a low-to
// moderate load application.

$fn = 64;

// ---- Dimensions (mm) ----
flange_w   = 14;   // flange width (Y)
flange_t   = 2.5;  // flange thickness (Z)
neck_w     = 6;    // neck width (Y)
neck_h     = 5.5;  // neck height above flange (Z)
length     = 20;   // part length along X
screw_d    = 3.4;  // central screw hole diameter
eps        = 0.5;  // cutter overshoot past faces

// ---- Derived ----
total_h = flange_t + neck_h;  // overall height (Z)

// ---- Model ----
difference() {
    union() {
        // Bottom flange: y = -flange_w/2 .. flange_w/2, z = 0 .. flange_t
        translate([-length/2, -flange_w/2, 0])
            cube([length, flange_w, flange_t]);

        // Centred neck: y = -neck_w/2 .. neck_w/2, z = flange_t .. total_h
        translate([-length/2, -neck_w/2, flange_t])
            cube([length, neck_w, neck_h]);
    }

    // Vertical screw hole through the centre
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = total_h + 2*eps);
}
