// Stiffened cover panel: flat plate with 4 longitudinal ribs
// Units: mm. Print orientation: plate flat on bed, ribs pointing up (+Z).

// ---------------- Parameters ----------------
plate_len      = 100;   // plate length along X
plate_wid      = 60;    // plate width along Y
plate_thk      = 3;     // plate thickness (z = 0 to 3)

rib_thk        = 3;     // rib thickness along X
rib_h          = 6;     // rib height above plate (z = 3 to 9)
rib_count      = 4;     // number of ribs
rib_pitch      = 20;    // centre-to-centre spacing of ribs
rib_outer_dist = 20;    // centre of outer ribs to plate end

eps            = 0.5;   // overlap so cutters pass through faces

$fn = 64;

// ---------------- Derived ----------------
plate_z0 = 0;
plate_z1 = plate_thk;
rib_z0   = plate_z1;
rib_z1   = rib_z0 + rib_h;
x0       = -plate_len/2;
x1       = plate_len/2;

// Check: 4 ribs at pitch 20 with 20 mm end clearances span 100 mm
assert(abs(rib_count*rib_pitch + 2*rib_outer_dist - plate_len) < 0.001,
       "Rib parameters do not fill the plate length");

// ---------------- Model ----------------
union() {
    // Base plate
    translate([x0, -plate_wid/2, plate_z0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, evenly spaced along X
    for (i = [0 : rib_count - 1]) {
        x_c = rib_outer_dist + i * rib_pitch;
        translate([x_c - rib_thk/2, -plate_wid/2, rib_z0])
            cube([rib_thk, plate_wid, rib_h + eps]); // extend past top face
    }
}
