// Powder measuring scoop - hollow spherical bowl with flat handle
// Units: mm. Print orientation: bowl bottom on bed (z = 0), handle along +X.

// ---------- Parameters ----------
bowl_outer_radius   = 15;    // outer radius of spherical bowl
bowl_wall_thickness = 1.5;   // thickness of bowl wall
bowl_centre         = [0, 0, 15]; // sphere centre (lower half kept)
handle_width        = 12;    // handle width (Y)
handle_thickness    = 4;     // handle thickness (Z), top face flush with rim
handle_x_start      = 13.5;  // handle start (X), above rim
handle_x_end        = 75;    // handle end (X)
cut_extra           = 0.5;   // overshoot for cutting shapes past faces
fn_curve            = 96;    // facets for curved surfaces

// ---------- Derived ----------
bowl_inner_radius = bowl_outer_radius - bowl_wall_thickness;
handle_top_z      = bowl_centre[2] - bowl_wall_thickness; // z = 11 to 15

// ---------- Model ----------
union() {
    // Hollow spherical bowl (lower half)
    difference() {
        sphere(r = bowl_outer_radius, $fn = fn_curve);
        translate([0, 0, -cut_extra])
            sphere(r = bowl_inner_radius, $fn = fn_curve);
    }
    // Keep only lower half of bowl (z <= bowl_centre[2])
    clip = translate([0, 0, -1])
            hull() { for (x = [-bowl_outer_radius, bowl_outer_radius])
                        translate([x, 0, 0]) sphere(r = bowl_outer_radius, $fn = fn_curve); }
    difference() {
        clip;
        translate([0, 0, bowl_centre[2] - 0.01])
            cube([2 * bowl_outer_radius, 2 * bowl_outer_radius, 0.02]);
    }

    // Flat handle along +X, centred on y = 0
    translate([handle_x_start, -handle_width / 2, handle_top_z])
        cube([handle_x_end - handle_x_start, handle_width, handle_thickness]);
}
