// Eccentric cam for shaker mechanism
// Print orientation: disc flat on bed, hub pointing up (+Z)
// Shaft axis = Z axis (x=0, y=0); disc centre offset in +X

$fn = 96;

// --- Disc (eccentric lobe) ---
disc_d      = 30;   // disc diameter
disc_t      = 6;    // disc thickness (z = 0 .. 6)
eccentric   = 4;    // disc centre offset from shaft axis along X

// --- Hub (on shaft axis) ---
hub_d       = 16;   // hub diameter
hub_h       = 5;    // hub height above disc (z = 6 .. 11)

// --- Shaft bore ---
bore_d      = 8;    // shaft hole diameter, through hub and disc

// --- Misc ---
eps         = 0.5;  // overshoot for clean boolean cuts
overlap     = 0.01; // small overlap to fuse hub into disc

difference() {
    union() {
        // Eccentric disc, centred at (eccentric, 0)
        translate([eccentric, 0, 0])
            cylinder(d = disc_d, h = disc_t);

        // Hub on shaft axis, sitting on top of disc
        translate([0, 0, disc_t - overlap])
            cylinder(d = hub_d, h = hub_h + overlap);
    }

    // Shaft bore through hub and disc along Z axis
    translate([0, 0, -eps])
        cylinder(d = bore_d, h = disc_t + hub_h + 2 * eps);
}
