// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 3;     // specimen thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // transition section length (X)

// Derived
grip_count     = 2;     // grip sections (left and right)
transition_count = 2;   // transition sections
cut_extra      = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Model ----------
difference() {
    // Solid block
    translate([-total_length/2, -thickness/2, 0])
        cube([total_length, thickness, thickness]);

    // Grip cutouts (full Y, partial X)
    for (i = [0 : grip_count - 1]) {
        x0 = -total_length/2 + grip_length + i*(gauge_length + 2*transition_len);
        translate([x0 - cut_extra, -thickness/2 - cut_extra, 0])
            cube([grip_length + 2*cut_extra, grip_width + thickness + 2*cut_extra, thickness + 2*cut_extra]);
    }

    // Transition cutouts (width changes linearly from grip to gauge)
    for (i = [0 : transition_count - 1]) {
        x0 = -total_length/2 + grip_length + i*(gauge_length + 2*transition_len);
        w1 = grip_width;
        w2 = gauge_width + (grip_width - gauge_width) * (transition_len - x0) / transition_len;
        translate([x0 - cut_extra, -thickness/2 - cut_extra, 0])
            cube([transition_len + 2*cut_extra, w1 + w2 + thickness + 2*cut_extra, thickness + 2*cut_extra]);
    }
}
```

