```openscad
// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 3;     // specimen thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // transition section length (X)

// Derived
grip_count     = 2;     // number of grip sections
cutout         = 0.5;   // overcut for clean differences

// Check: 2*grip_length + gauge_length + 2*transition_len
//        = 50 + 40 + 30 = 120 mm

// ---------- Model ----------
difference() {
    // Outer shape: grip -> transition -> gauge -> transition -> grip
    union() {
        for (i = [0 : grip_count - 1]) {
            // Grip sections, centred on end X positions
            translate([-total_length / 2 + grip_length + i * (grip_length + transition_len),
                       -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);
        }
        // Gauge section, centred on origin
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);
        // Transition sections, width changes linearly from grip to gauge
        for (i = [0 : grip_count - 1]) {
            x0 = -total_length / 2 + grip_length + i * (grip_length + transition_len);
            w0 = grip_width;
            w1 = gauge_width;
            translate([x0, -w0 / 2, 0])
                linear_extrude(thickness)
                    polygon([[-transition_len, 0], [0, w1 - w0], [transition_len, 0]]);
        }
    }

    // Cut out a central rectangle in each grip, running through the full X length
    for (i = [0 : grip_count - 1]) {
        x = -total_length / 2 + grip_length + i * (grip_length + transition_len);
        translate([x - cutout, -gauge_width / 2, -cutout])
            cube([total_length, gauge_width, thickness + 2 * cutout]);
    }
}
