// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 4;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 15;    // transition section length (X)

// Derived
gauge_x0       = -total_length/2 + grip_length + transition_len;  // gauge start X
// ---------- Model ----------
difference() {
    union() {
        // Left grip
        translate([-total_length/2, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([gauge_x0, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right grip
        translate([gauge_x0 + gauge_length + transition_len, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            x0 = s > 0 ? gauge_x0 + gauge_length : -total_length/2;
            w0 = grip_width;
            w1 = gauge_width;
            translate([x0, -w0/2, 0])
                linear_extrude(thickness)
                    polygon([[-transition_len, w0 - s*(w0 - w1)],
                             [0, w1 - s*(w0 - w1)]]);
        }
    }

    // Cut a central hole through the gauge section
    translate([gauge_x0 + gauge_length/2 - 2, -4, -1])
        cube([gauge_length/2 + 2, gauge_width + 8, thickness + 2]);
}
