    translate([-total_length/2 - cut_extra, -gauge_width/2 - cut_extra, 0])
        cube([total_length + 2*cut_extra, gauge_width + 2*cut_extra, thickness + cut_extra]);

    translate([x_mid - cut_extra, -gauge_width/2 - cut_extra, 0])
        cube([total_length + 2*cut_extra, gauge_width + 2*cut_extra, thickness + cut_extra]);
