// ---------- Parameters ----------
thickness      = 4;     // specimen thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 10;    // transition section length (X)
cut_extra      = 0.5;   // cutter overshoot past end faces

$fn = 64;

// ---------- Derived ----------
head_start = -total_length / 2 + grip_length;              // first grip begins
gauge_x0   = head_start + grip_length + transition_len;    // gauge starts
head_end   = total_length / 2 - grip_length;               // second grip ends

// ---------- Model ----------
difference() {
    union() {
        // Left grip
        translate([head_start - cut_extra, -grip_width / 2, 0])
            cube([grip_length + cut_extra * 2, grip_width, thickness]);

        // Gauge section
        translate([gauge_x0 - cut_extra, -gauge_width / 2, 0])
            cube([gauge_length + cut_extra * 2, gauge_width, thickness]);

        // Right grip
        translate([head_end - cut_extra, -grip_width / 2, 0])
            cube([grip_length + cut_extra * 2, grip_width, thickness]);

        // Transitions (width changes linearly from 15 to 8 mm)
        for (s = [-1, 1]) {
            x0 = s < 0 ? head_start + grip_length : head_end - grip_length;
            translate([x0 - cut_extra, -grip_width / 2, 0])
                cube([transition_len + cut_extra * 2,
                      grip_width + s * (grip_width - gauge_width),
                      thickness]);
        }
    }

    // Cutters that extend past the end faces
    translate([head_start - cut_extra, -grip_width / 2, 0])
        cube([cut_extra, grip_width, thickness]);

    translate([head_end - cut_extra, -grip_width / 2, 0])
        cube([cut_extra, grip_width, thickness]);
