```openscad
// T-shaped extrusion nut - slides into the slot of an aluminium profile.
// Print orientation: flange on the bed (z = 0), neck pointing up.
//
// NOTE: This is a solid parts file, not a model that generates a lattice
// or any internal honeycomb structure. It has no horizontal layers at z = 3
// and no patterned cutouts - just the T-shaped block with a screw hole.
//
// Parameters (mm):
//   flange_w   - flange width (Y)
//   flange_t   - flange thickness (z = 0 to 2)
//   neck_w     - neck width (Y), centred on flange
//   neck_h     - neck height above flange (z = 2 to 8)
//   length     - part length along X
//   screw_d    - screw hole diameter
//   overcut    - extra length on cutters to avoid coplanar faces

$fn = 64;

flange_w   = 12;
flange_t   = 2;
neck_w     = 6;
neck_h     = 6;
length     = 20;
screw_d    = 3.4;
overcut    = 0.5;

difference() {
    union() {
        // Bottom flange: y = -flange_w/2 .. flange_w/2, z = 0 .. flange_t
        translate([-length/2, -flange_w/2, 0])
            cube([length, flange_w, flange_t]);

        // Neck: y = -neck_w/2 .. neck_w/2, z = flange_t .. flange_t + neck_h
        translate([-length/2, -neck_w/2, flange_t])
            cube([length, neck_w, neck_h]);
    }

    // Central screw hole, through the full height
    translate([0, 0, -overcut])
        cylinder(d = screw_d, h = flange_t + neck_h + 2*overcut);
}
```

