// Print orientation: wide base on bed (z = 0), narrowing upward

$fn = 128;

// --- Dimensions (mm) ---
base_d      = 30;    // frustum diameter at bottom (z = 0)
top_d       = 20;    // frustum diameter at flat top
foot_h      = 15;    // overall height
recess_d    = 22;    // rubber pad recess diameter (bottom face)
recess_depth = 3;    // rubber pad recess depth
screw_d     = 5.5;   // through hole diameter for screw

eps = 0.5;           // overlap for clean boolean cuts

difference() {
    // Frustum body
    cylinder(h = foot_h, d1 = base_d, d2 = top_d);

    // Rubber pad recess in bottom face
    translate([0, 0, -eps])
        cylinder(h = recess_depth + eps, d = recess_d);

    // Central screw through hole
    translate([0, 0, -eps])
        cylinder(h = foot_h + 2 * eps, d = screw_d);
}
