// Stiffened cover panel: flat plate with 3 longitudinal ribs
// Units: mm. Print orientation: plate flat on bed, ribs pointing up (+Z).

// ---------------- Parameters ----------------
plate_len   = 80;    // plate length along X
plate_wid   = 80;    // plate width along Y
plate_thk   = 2;     // plate thickness (z = 0 to 2)

rib_thk     = 2;     // rib thickness along X
rib_h       = 6;     // rib height above plate (z = 2 to 8)
rib_count   = 3;     // number of ribs
rib_pitch   = 20;    // centre-to-centre spacing of ribs along X
rib_offset  = 20;    // distance from plate end to outer rib centre

eps         = 0.5;   // cutter overshoot past cut faces

$fn = 64;

// ---------------- Derived ----------------
plate_z0 = 0;
plate_z1 = plate_thk;
rib_z0   = plate_z1;   // ribs start at top of plate
rib_z1   = rib_z0 + rib_h;

// Check: rib_count * pitch + 2 * offset = 3*20 + 2*20 = 100 mm (plate + overhangs)
assert(abs(rib_count * rib_pitch + 2 * rib_offset - plate_len) < 0.001,
       "Rib layout does not match plate length.");

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, plate_z0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, centred on X = -offset, 0, +offset
    for (i = [0 : rib_count - 1]) {
        x_c = (i - (rib_count - 1)/2) * rib_pitch + (rib_count % 2 == 1 ? 0 : 0);
        // x_c is -20, 0, +20 for the 3 ribs
        translate([x_c - rib_thk/2, -plate_wid/2, rib_z0])
            cube([rib_thk, plate_wid, rib_h]);
    }
}
```

