// Stiffened cover panel: flat plate with 5 longitudinal ribs
// Units: mm. Print orientation: plate on bed (z = 0), ribs build upward.

// ---------- Parameters ----------
plate_len   = 120;   // plate length along X
plate_wid   = 60;    // plate width along Y
plate_thk   = 3;     // plate thickness (z = 0 to 3)

rib_thk     = 3;     // rib thickness along X
rib_h       = 6;     // rib height above plate (z = 3 to 9)
rib_count   = 5;     // number of ribs
rib_pitch   = 20;    // centre-to-centre spacing of ribs
rib_overrun = 0.5;   // extra length of cutters past plate end faces

$fn = 64;

// ---------- Derived ----------
plate_x0 = -plate_len / 2;        // plate start in X
plate_x1 = plate_len / 2;         // plate end in X
rib_z0   = plate_thk;             // rib bottom (on top of plate)
rib_z1   = rib_z0 + rib_h;        // rib top

// Check: 5 ribs at 20 mm pitch occupy 80 mm; two end gaps of 20 mm
// leave 120 mm total. Outer ribs are therefore 20 mm from the ends.
assert(abs(rib_count * rib_pitch + 2 * rib_pitch - plate_len) < 0.001,
       "Rib parameters do not add up to the plate length.");

// ---------- Model ----------
union() {
    // Flat plate
    translate([plate_x0, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, centred on the plate axis
    for (i = [0 : rib_count - 1]) {
        x_c = i * rib_pitch - (rib_count - 1) * rib_pitch / 2;
        translate([x_c - rib_thk / 2, -plate_wid / 2, rib_z0])
            cube([rib_thk, plate_wid, rib_h]);
    }
}
