// ---------- Model ----------
union() {
    // Base plate, centred in X and Y
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_t]);

    // Ribs at x = -40, -20, 0, 20, 40
    for (i = [1 : rib_count]) {
        x_c = -plate_len/2 + i * rib_pitch;
        translate([x_c - rib_t/2, -rib_len/2, plate_t - overlap])
            cube([rib_t, rib_len, rib_h + overlap]);
    }
}
