// Powder measuring scoop - hollow spherical bowl with flat handle
// Units: mm. Print orientation: bowl bottom on bed (z = 0), handle along +X.

// ---------- Parameters ----------
bowl_outer_radius   = 15;    // outer radius of spherical bowl
bowl_wall_thickness = 1.5;   // thickness of bowl wall
bowl_centre         = [0, 0, 15]; // sphere centre (lower half kept)
handle_width        = 10;    // handle width (Y)
handle_thickness    = 4;     // handle thickness (Z)
handle_start_x      = 13.5;  // handle start (X), above rim
handle_end_x        = 75;    // handle end (X)
overcut             = 0.5;   // extra length of cutters past faces
$fn                 = 96;    // curve resolution

// ---------- Derived ----------
bowl_inner_radius = bowl_outer_radius - bowl_wall_thickness;
handle_top_z      = bowl_centre[2] - bowl_wall_thickness; // flush with rim (z = 11)

// ---------- Model ----------
union() {
    // Hollow spherical bowl (lower half)
    difference() {
        sphere(r = bowl_outer_radius, d = 30);
        translate([0, 0, -overcut])
            sphere(r = bowl_inner_radius, d = 2 * bowl_inner_radius);
    }
    // Flat handle, top face at z = 11..15
    translate([handle_start_x, -handle_width / 2, handle_top_z])
        cube([handle_end_x - handle_start_x, handle_width, handle_thickness]);
}
