        // Bowl: lower half of hollow sphere
        translate([0, 0, bowl_z0])
            cylinder(r = bowl_r, h = bowl_r + 0.01, $fn = 128);   // outer
        translate([0, 0, bowl_z0 + wall])
            cylinder(r = bowl_r - wall, h = bowl_r + 0.01, $fn = 128); // inner

        // Handle: flat plate, top face flush with rim (z = 11..15)
        translate([handle_x0, -handle_w / 2, bowl_z0 - handle_t])
            cube([handle_x1 - handle_x0, handle_w, handle_t + 0.01]);
