    // Cut a small pocket under the rim so the handle blends into the bowl
    translate([handle_x0 - eps, -handle_w / 2 - eps, bowl_z0 - handle_t - eps])
        cube([handle_x1 - handle_x0 + 2 * eps, handle_w + 2 * eps, handle_t + 2 * eps]);
