            cylinder(r = bowl_r, h = bowl_z, $fn = 128);
        translate([0, 0, bowl_z - wall])
            cylinder(r = bowl_r - wall, h = bowl_z - wall + 0.01, $fn = 128);

        // Handle: flat plate, top face flush with rim (z = 8..12)
        translate([handle_x0, -handle_w / 2, bowl_z - wall])
            cube([handle_x1 - handle_x0, handle_w, wall + 0.01]);
