// Powder measuring scoop: hemispherical bowl with a flat handle
// Print orientation: bowl bottom on the bed (z = 0), opening upward

$fn = 96;

// ---- Bowl ----
bowl_r_outer = 12;      // outer radius of bowl sphere
bowl_wall    = 2;       // wall thickness
bowl_r_inner = bowl_r_outer - bowl_wall;  // inner radius (10)
bowl_cz      = 12;      // sphere centre height (rim height)

// ---- Handle ----
handle_x0    = 10;      // handle start along +X
handle_x1    = 72;      // handle end along +X
handle_w     = 10;      // handle width (Y)
handle_t     = 4;       // handle thickness (Z)
handle_top   = 12;      // handle top face (flush with rim)

eps = 0.5;              // overlap for clean boolean cuts

module bowl() {
    difference() {
        translate([0, 0, bowl_cz]) sphere(r = bowl_r_outer);
        translate([0, 0, bowl_cz]) sphere(r = bowl_r_inner);
        // remove upper half (everything above the rim)
