// Pin hinge leaf
// Print orientation: flat on bed, knuckles above (z = 3.5 .. 10.5)

$fn = 64;

// ---- Plate ----
plate_len   = 45;   // plate length along X
plate_wid   = 20;   // plate width along Y
plate_thk   = 3;    // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 7;    // knuckle diameter
knuckle_z   = 3.5;  // knuckle axis height (z)
knuckle_n   = 3;    // number of knuckles
knuckle_w   = 15;   // segment length per knuckle (X)
knuckle_y   = 10;   // knuckle axis Y position

// ---- Pin ----
pin_d       = 3;    // pin diameter

// ---- Misc ----
eps         = 0.5;  // cutter overshoot past faces

// Knuckle X centre offsets: 1st and 3rd segments
function knuckle_x(i) = (i - 1) * knuckle_w;

difference() {
    union() {
        // Plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders along X axis
        for (i = [0 : knuckle_n - 1])
            translate([knuckle_x(i), knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = 7, $fn = 96);
    }

    // Pin holes along X axis through every knuckle
    for (i = [0 : knuckle_n - 1])
        translate([knuckle_x(i), knuckle_y, knuckle_z])
            translate([-eps, 0, -eps])
                cylinder(d = pin_d, h = knuckle_d + 2*eps, $fn = 64);
}
