// Pin hinge leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 45;    // plate length along X
plate_wid   = 25;    // plate width along Y
plate_thk   = 3;     // plate thickness along Z

knuckle_d   = 8;     // knuckle (cylinder) diameter
knuckle_z   = 4;     // knuckle axis height above bed
knuckle_y   = 12.5;  // knuckle axis Y position
knuckle_n   = 3;     // number of knuckles
knuckle_w   = 15;    // length of each knuckle segment along X
knuckle_h   = 2;     // pin hole diameter

eps         = 0.5;   // cutter overshoot past faces
$fn         = 96;    // curve resolution

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on +Y edge: 1st and 3rd segments
        for (i = [0 : knuckle_n - 1]) {
            x0 = (i - (knuckle_n - 1)/2) * knuckle_w;
            if (i == 0 || i == knuckle_n - 1)   // 1st and 3rd
                translate([x0, knuckle_y, knuckle_z])
                    cylinder(d = knuckle_d, h = knuckle_w, $fn = $fn);
        }
    }

    // Pin holes along the knuckle axes
    for (i = [0 : knuckle_n - 1]) {
        x0 = (i - (knuckle_n - 1)/2) * knuckle_w;
        translate([x0, knuckle_y, knuckle_z])
            cylinder(d = knuckle_h, h = knuckle_w + 2*eps, $fn = $fn);
    }
}
