// ---------- Model ----------
difference() {
    // Main frustum body: build upward from z = 0 with sloping sides
    translate([0, 0, 0])
        linear_extrude(height = height)
            polygon([[-base_size/2, -base_size/2],
                     [-base_size/2, base_size/2],
                     [ top_size/2, base_size/2],
                     [ top_size/2, -base_size/2]]);

    // Square pocket cut into the top face, centred, open upward
    translate([0, 0, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
