// Tapered riser block (square frustum) with top pocket
// Print orientation: base on bed, builds upward (+Z)

bottom_size  = 100;   // bottom square side (mm)
top_size     = 80;    // top square side (mm)
height       = 25;    // overall height (mm)
pocket_size  = 70;    // pocket square side (mm)
pocket_depth = 8;     // pocket depth from top face (mm)
