$fn           = 64;   // curve resolution (applies to auxiliary curved shapes)

// ---------------- Derived ----------------
// Side length of the square at an arbitrary height z (linear interpolation)
function side(z) = bottom_size + (top_size - bottom_size) * z / height;

// ---------------- Model ----------------
union() {
    // Frustum body: difference between a bottom cylinder (circle with side = diameter)
    // and a top cylinder, both centred on the origin in XY.
    difference() {
        cylinder(h = height, d = side(0));
        translate([0, 0, eps])
            cylinder(h = height + 2 * eps, d = side(height));
    }

    // Square pocket cut into the top face, centred and open at the top
    translate([0, 0, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
