    if (x < gauge_x0 - transition_len / 2)
        return grip_width;
    if (x > gauge_x0 + transition_len / 2)
        return gauge_width;
    // between grip and gauge
    return gauge_width + (grip_width - gauge_width) *
           (x - (gauge_x0 - transition_len / 2)) / transition_len;
}

difference() {
    translate([-total_length / 2, -thickness / 2, 0])
        cube([total_length, thickness, thickness]);

    for (sx = [-1, 1])
        translate([sx * (total_length / 2 - grip_length - 1), -eps, 0])
            cube([total_length / 2 - grip_length - 1, grip_width + 2 * eps, thickness]);
