    union() {
        // Left grip
        translate([head_start, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge
        translate([g1, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right grip
        translate([t_start, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            x0 = (s < 0) ? g1 : t_start;
            w0 = grip_width;
            w1 = (s < 0) ? gauge_width : grip_width;
            translate([x0, -w0 / 2, 0])
                linear_extrude(thickness)
                    polygon([[-transition_len, -w0 / 2],
                             [-transition_len, w0 / 2],
                             [0, w1 / 2],
                             [0, -w1 / 2]]);
        }
    }

