// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 3;     // specimen thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 10;    // transition section length (X)
eps            = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
head_start = -total_length / 2 + grip_length;        // first grip begins
gauge_x0   = head_start + grip_length + transition_len;  // gauge starts
head_end   = total_length / 2 - grip_length;          // last grip ends

// ---------- Width profile ----------
function w(x) =
    x < head_start || x > head_end     ? grip_width :
    x < gauge_x0                       ? grip_width + (gauge_width - grip_width) * (x - head_start) / transition_len :
    x > gauge_x0 + gauge_length        ? grip_width + (gauge_width - grip_width) * (head_end - x) / transition_len :
    gauge_width;

// ---------- Model ----------
difference() {
    translate([-total_length / 2, -thickness / 2, 0])
        cube([total_length, thickness, thickness]);

    for (s = [-1, 1])
        translate([s * (head_start - eps), -thickness / 2 - eps, 0])
            cube([head_end - head_start + 2 * eps, thickness + 2 * eps, thickness]);
}
