$fn = 64;

// ---------- Derived ----------
grip_x0 = -total_length/2 + grip_length + transition_len;   // left grip start X
gauge_x0 = grip_x0 + grip_length;                           // gauge start X
right_x0 = gauge_x0 + gauge_length;                         // right grip start X

// ---------- Model ----------
difference() {
    // Outer shape: two grip blocks + two transition blocks + gauge block
    union() {
        // Left grip
        translate([grip_x0, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Right grip
        translate([right_x0, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            x0 = s > 0 ? gauge_x0 - transition_len : grip_x0;
            w0 = s > 0 ? gauge_width : grip_width;
            translate([x0, -w0/2, 0])
                cube([transition_len, grip_width - w0, thickness]);
        }

        // Gauge section
        translate([gauge_x0, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);
    }

    // Central cutout: rectangle through the full thickness, centred on origin
    translate([-gauge_length/2, -gauge_width/2, -eps])
        cube([gauge_length, gauge_width, thickness + 2*eps]);
}
