// Stiffened cover panel: flat plate with 5 longitudinal ribs
// Units: mm. Print orientation: plate flat on bed, ribs pointing up (+Z).

// ---------------- Parameters ----------------
plate_len      = 120;   // plate length along X
plate_wid      = 60;    // plate width along Y
plate_thk      = 3;     // plate thickness (z = 0 to 3)

rib_thk        = 3;     // rib thickness along X
rib_h          = 5;     // rib height above plate (z = 3 to 8)
rib_count      = 5;     // number of ribs
rib_pitch      = 20;    // centre-to-centre spacing of ribs
rib_outer_dist = 20;    // distance from outer rib centre to plate end

eps            = 0.5;   // cutter overshoot past faces
$fn            = 64;    // curve resolution (no curves here, set per rules)

// ---------------- Derived ----------------
rib_n     = rib_count + 1;   // number of open cells between ribs
cell_w    = rib_pitch;       // each cell is one pitch wide
overhang  = rib_h - plate_thk; // = 2 mm, the part the cutters sink into

// ---------------- Model ----------------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, centred on the length axis
    for (i = [0 : rib_count]) {
        x_c = (i - rib_count/2) * rib_pitch + (i < rib_count/2 ? rib_outer_dist : -rib_outer_dist);
        translate([x_c - rib_thk/2, -plate_wid/2, plate_thk])
            cube([rib_thk, plate_wid, rib_h]);
    }

    // Clean up small open cells (20 mm long, 3 mm wide) between ribs
    for (j = [0 : rib_n]) {
        translate([-plate_len/2 + j * cell_w - eps, -cell_w/2 - eps, plate_thk - overhang])
            cube([cell_w + 2*eps, cell_w + 2*eps, overhang + eps]);
    }
}
