        translate(bowl_centre)
            cylinder(r = outer_r, h = 30, $fn = 96);               // outer shell
        translate(bowl_centre)
            cylinder(r = outer_r - wall, h = 30, $fn = 96);        // inner cavity
        // Handle: flat plate, top face flush with rim (z = 12 to 15)
        translate([handle_x0, -handle_w / 2, 12])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }
    // Cut the upper half of the inner cavity (z > 15), open at the rim
    translate(bowl_centre)
        cylinder(r = outer_r - wall + eps, h = eps, $fn = 96);
    // Cut a small pocket under the handle start so the union is manifold
    translate([handle_x0 - 2, -handle_w / 2, 0])
        cube([2, handle_w, 0.01]);
