difference() {
    // Main block
    translate([-bridge_len/2, -bridge_wid/2, 0])
        cube([bridge_len, bridge_wid, bridge_ht]);

    // Semicircular tunnels (cylinder axes along Y at z = 0)
    for (i = [0 : tunnel_n - 1]) {
        x_c = (i - (tunnel_n - 1)/2) * tunnel_pitch;
        translate([x_c, -overcut, 0])
            rotate([90, 0, 0])
                cylinder(d = tunnel_d, h = bridge_wid + 2*overcut);
