ring_r      = 22;    // torus revolution radius (distance of cross-section centre from Z axis)
ring_h      = 6;     // torus middle plane height (z of the centreline of the cross-section)
eps         = 0.5;   // cutter overshoot past faces to avoid coplanar surfaces
$fn         = 128;   // curve resolution

// Derived
minor_r = ring_d / 2;   // minor radius (cross-section radius)
major_r = ring_r;       // major radius (revolution radius)
thickness = ring_h;     // overall thickness along Z (2 * minor_r for a full torus)

// Check: ring spans X/Y from (major_r - minor_r) to (major_r + minor_r)
//        -> 22 - 6 = 16 mm to 22 + 6 = 28 mm across the origin (56 mm total width)

// ---------------- Model ----------------
difference() {
    // Solid cylinder along Z, centred on the torus centreline circle
    translate([0, 0, ring_h - minor_r])
        cylinder(h = thickness + 2 * eps, r = major_r + minor_r);

    // Through-bore: a cylinder along Z whose axis lies in the XY plane at
    // distance major_r from the origin, running past both top and bottom faces
    translate([major_r, 0, -eps])
        rotate([0, 90, 0])
            cylinder(h = thickness + 2 * eps, r = minor_r);
}
