        // Plate, centred in X/Y, resting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders, overlapping at the ends
        for (i = [0 : knuckle_n - 1]) {
            translate([first_x + i * pitch, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 2 * overlap);
        }
    }

    // Pin holes along the common axis through every knuckle
    for (i = [0 : knuckle_n - 1]) {
        translate([first_x + i * pitch, knuckle_y, knuckle_z])
            cylinder(d = pin_d, h = plate_thk + 2 * eps);
