    // Pin holes along X through every knuckle
    for (i = [0 : knuckle_n - 1]) {
        if (i % 2 == 0) {
            translate([-knuckle_step/2 + i * knuckle_step,
                       knuckle_y,
                       knuckle_z - eps])
                cylinder(d = pin_d, h = plate_thk + 2 * eps, center = true);
        }
    }
}
