// Pin hinge leaf: flat plate with two outer knuckles along the +Y edge
// Print orientation: plate flat on the bed (z = 0), knuckles build upward

// ---------- Dimensions (mm) ----------
plate_len    = 45;    // plate length along X
plate_wid    = 25;    // plate width along Y
plate_thk    = 2.5;   // plate thickness (Z)

n_segments   = 3;                       // hinge length divided into segments
seg_len      = plate_len / n_segments;  // 15 mm per segment

knuckle_d    = 7;     // knuckle outer diameter
axis_y       = 12.5;  // hinge axis Y position (on +Y plate edge)
axis_z       = 3.5;   // hinge axis Z height (knuckle bottom touches bed)

pin_hole_d   = 3;     // pin hole diameter
hole_ext     = 0.3;   // how far the hole cutter extends past each knuckle face

knuckle_segs = [0, 2]; // indices of segments carrying knuckles (1st and 3rd)

$fn = 96;

// ---------- Helpers ----------
// X start of segment i
function seg_x0(i) = -plate_len / 2 + i * seg_len;

// Cylinder along +X starting at x0, length len, diameter d, on the hinge axis
module axis_cyl(x0, len, d) {
    translate([x0, axis_y, axis_z])
        rotate([0, 90, 0])
            cylinder(h = len, d = d);
}

// ---------- Model ----------
difference() {
    union() {
        // Flat plate, centred in X and Y
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the 1st and 3rd segments
        for (i = knuckle_segs)
            axis_cyl(seg_x0(i), seg_len, knuckle_d);
    }

    // Pin hole through every knuckle, slightly longer than each knuckle
    for (i = knuckle_segs)
        axis_cyl(seg_x0(i) - hole_ext, seg_len + 2 * hole_ext, pin_hole_d);
}
