total_length   = 110;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len  = 15;    // transition section length (X)

// Derived
grip_start_x   = -total_length/2 + grip_length;  // -42.5
gauge_start_x  = grip_start_x + grip_length;     // -17.5
gauge_end_x    = gauge_start_x + gauge_length;   // 13
transition_end_x = gauge_end_x + transition_len; // 28
grip_end_x     = transition_end_x + transition_len; // 63
right_grip_start_x = grip_end_x;                 // 63
right_grip_end_x   = right_grip_start_x + grip_length; // 88

// Check: 2*25 + 30 + 2*15 = 110 mm

module width(x) {
    // width = grip_width + (gauge_width - grip_width) * normalized_dist
    return grip_width + (gauge_width - grip_width) *
           (x - gauge_start_x) / transition_len;
}

difference() {
    translate([-total_length/2, -thickness/2, 0])
        linear_extrude(thickness)
            polygon([[-total_length/2, 0], [right_grip_end_x, 0]]);

    // Cut out the two grip regions and the central gauge region
    for (sx = [grip_start_x, right_grip_start_x])
        translate([sx - grip_length - 0.01, -thickness/2 - 0.01, 0])
            cube([grip_length + 0.02, thickness + 0.02, height = thickness + 0.02]);

    translate([gauge_start_x - 0.01, -thickness/2 - 0.01, 0])
        cube([gauge_length + 0.02, thickness + 0.02, height = thickness + 0.02]);
