            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([gauge_x0, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right grip
        translate([gauge_x0 + gauge_length + transition_len, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
    }

    // Cut out the central region of each transition (keeps wall > 1 mm)
    for (s = [-1, 1]) {
        x1 = s > 0 ? gauge_x0 + gauge_length : -total_length/2;
        x2 = x1 + transition_len;
        w1 = s > 0 ? grip_width : gauge_width;
        w2 = s > 0 ? gauge_width : grip_width;
        translate([x1 - 0.01, -w1/2, 0])
            linear_extrude(thickness + 0.01)
                polygon([[-transition_len, w1 - gauge_width],
                         [0, w2 - gauge_width]]);
