        translate([-total_length/2, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        // Right grip
        translate([total_length/2 - grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        // Gauge section
        translate([gauge_x0, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);
        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            x1 = s > 0 ? total_length/2 - grip_length : -total_length/2;
            x2 = gauge_x0;
            translate([x1, -grip_width/2, 0])
                linear_extrude(thickness)
                    polygon([[-x2, -gauge_width/2], [-x2, gauge_width/2],
                            [x2, -grip_width/2], [x2, grip_width/2]]);
        }
    }
    // Small cutouts along X to avoid coplanar faces
    for (x = [-total_length/2, gauge_x0 + gauge_length/2, total_length/2])
        translate([x, 0, -1]) cube([2, total_length, 2]);
}
