// Print orientation: flange on the bed (z = 0), neck pointing up (+Z).
//
// NOTE: This part models only the nut that holds the profile in place.
// It does not model the aluminium extrusion itself.
//
// ---------------- Parameters ----------------
flange_w   = 14;    // flange width (Y)
flange_t   = 2.5;   // flange thickness (Z)
neck_w     = 6;     // neck width (Y)
neck_h     = 6.5;   // neck height above flange (Z)
length     = 10;    // profile length along X
screw_d    = 3.4;   // central screw hole diameter
eps        = 0.5;   // cutter overshoot past faces
$fn        = 64;    // curve resolution

// ---------------- Model ----------------
difference() {
    union() {
        // Bottom flange: y = -flange_w/2 .. flange_w/2, z = 0 .. flange_t
        translate([-length/2, -flange_w/2, 0])
            cube([length, flange_w, flange_t]);

        // Centred neck: y = -neck_w/2 .. neck_w/2, z = flange_t .. flange_t + neck_h
        translate([-length/2, -neck_w/2, flange_t])
            cube([length, neck_w, neck_h]);
    }

    // Vertical screw hole through the centre of the part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = flange_t + neck_h + 2*eps);
}
```

