neck_w     = 6;    // neck width (Y), centred on flange
neck_h     = 3;    // neck height above flange (z = 2 to 5)
length     = 20;   // part length along X, centred on origin
screw_d    = 3.4;  // vertical screw hole diameter

eps        = 0.5;  // overshoot for clean boolean cuts

// ---- Model ----
difference() {
    union() {
        // Bottom flange: full width, centred in X and Y
        translate([-length / 2, -flange_w / 2, 0])
            cube([length, flange_w, flange_t]);

        // Neck: centred on the flange, rises to z = flange_t + neck_h
        translate([-neck_w / 2, -neck_w / 2, flange_t])
            cube([neck_w, neck_w, neck_h]);
    }

    // Vertical screw hole through the centre of the part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = flange_t + neck_h + 2 * eps);
}
