```openscad
// T-shaped extrusion nut - slides into the slot of an aluminium profile.
// Print orientation: flange on the bed (z = 0), neck pointing up (+Z).
//
// NOTE: This part is a screw slide, not a bearing. It is not designed to
// support axial loads or high speeds. Use with a coarse screw and at low
// speed. Do not use with dryfite or other low-friction liners in the slot.
//
// A 3.4 mm screw hole runs vertically through the centre of the part.

$fn = 64;

// ---- Dimensions (mm) ----
t      = 2;     // flange thickness (z = 0 to 2)
flange = 10;    // flange width along Y
neck   = 6;     // neck width above flange
h      = 5;     // total height of the T profile (z = 0 to 5)
len    = 20;    // length along X, centred on the origin
screw  = 3.4;   // central screw-hole diameter

// ---- Model ----
difference() {
    union() {
        // Bottom flange: full width along X, centred on the origin in X and Y
        translate([-len / 2, -flange / 2, 0])
            cube([len, flange, t]);

        // Neck: centred on the origin in X and Y, rising from z = t to z = h
        translate([-neck / 2, -neck / 2, t])
            cube([neck, neck, h - t]);
    }

    // Central screw hole, through the entire part (z = 0 to z = h)
    translate([0, 0, -1])
        cylinder(d = screw, h = h + 2);
}
```

