// Powder measuring scoop - hollow spherical bowl with flat handle
// Print orientation: bowl bottom on bed (z = 0), handle extending along +X

// ---------- Parameters ----------
bowl_outer_radius   = 12;   // outer radius of spherical bowl
wall_thickness      = 2;    // wall thickness of bowl
bowl_centre         = [0, 0, 12]; // centre of sphere (lower half kept)
handle_start_x      = 10;   // handle begins at x = 10
handle_end_x        = 72;   // handle ends at x = 72
handle_width        = 8;    // handle width along Y
handle_thickness    = 4;    // handle thickness along Z
cut_extra           = 0.5;  // overshoot for clean boolean cuts
$fn                 = 96;   // curve resolution

// ---------- Derived ----------
bowl_inner_radius = bowl_outer_radius - wall_thickness;
handle_top_z      = bowl_centre[2] - wall_thickness; // flush with rim (z = 8)

// ---------- Model ----------
union() {
    // Hollow spherical bowl (lower half)
    difference() {
        sphere(r = bowl_outer_radius, d = 2 * (bowl_centre[2] - 0.01));
        translate([0, 0, 0.01])
            sphere(r = bowl_inner_radius, d = 2 * (bowl_centre[2] - 0.01));
    }

    // Flat handle, top face flush with rim
    translate([handle_start_x, -handle_width / 2, handle_top_z])
        cube([handle_end_x - handle_start_x, handle_width, handle_thickness + cut_extra]);

    // Blend between bowl end and handle start
    hull() {
        translate([handle_start_x - 1, 0, 0])
            sphere(r = bowl_inner_radius / 2);
        translate([handle_start_x, -handle_width / 2, handle_top_z])
            cube([1, handle_width, handle_thickness]);
    }
}
