// Cable bridge for bench mat - 3 semicircular tunnels along Y at floor level
// Print orientation: block rests on XY plane, builds up +Z

// ---------- Parameters ----------
block_len   = 60;    // block length along X (mm)
block_wid   = 30;    // block width along Y (mm)
block_ht    = 12;    // block height along Z (mm)

tunnel_d    = 12;    // tunnel cylinder diameter (mm); axis at z = 0
tunnel_pitch = 20;   // centre-to-centre spacing of tunnel axes along X (mm)
tunnel_n    = 3;     // number of tunnels

eps         = 0.5;   // overshoot for clean boolean cuts (mm)
$fn         = 96;    // curve resolution

// ---------- Model ----------
difference() {
    // Main block, centred in X/Y, sitting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Semicircular tunnels: cylinder axis along Y, centre line along X
    for (i = [0 : tunnel_n - 1]) {
        x_c = (i - (tunnel_n - 1)/2) * tunnel_pitch;
        translate([x_c - tunnel_d/2, -tunnel_d/2, 0])
            rotate([0, 90, 0])
                cylinder(d = tunnel_d, h = block_wid + 2*eps, center = true);
    }
}
