    rotate_extrude() {
        translate([ring_radius, 0, base_height])
            cylinder(d = cross_section_d, h = ring_width, $fn = 128);
    }

    // Central through-hole along Z, extending past both faces
    translate([ring_radius, 0, base_height - cut_extra])
        cylinder(d = cross_section_d - 2, h = ring_width + 2 * cut_extra, $fn = 128);
