// Ring weight for flask in water bath - a flat torus lying on the bed
// Print orientation: flat on z = 0, middle plane at z = 8

// ---- Dimensions (mm) ----
cross_section_d      = 16;   // diameter of the round cross-section
ring_radius          = 20;   // radius of the circle the cross-section centre travels on
outer_diameter       = 56;   // overall diameter of the ring (2 * ring_radius + cross_section_d)
height               = 16;   // total height of the torus (2 * cross_section_d/2)
cut_extra            = 0.5; // overshoot for clean boolean cuts
$fn                  = 128;  // facet count for round features

// Derived
inner_diameter = outer_diameter - cross_section_d; // 40 mm bore

difference() {
    // Solid body: circle of ring_radius, extruded through the cross-section diameter
    translate([0, 0, 0])
        cylinder(r = ring_radius, h = cross_section_d, $fn = 256);

    // Central bore: a through-hole of inner_diameter, split along z so the cut
    // overshoots both the top and bottom faces by cut_extra
    translate([0, 0, -cut_extra])
        union() {
            cylinder(r = inner_diameter / 2, h = height / 2 + cut_extra + 0.01, $fn = 256);
            translate([0, 0, height / 2 - (height / 2 + cut_extra + 0.01)])
                cylinder(r = inner_diameter / 2, h = height / 2 + cut_extra + 0.01, $fn = 256);
        }
}
