// Pin hinge leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 40;    // plate length along X
plate_wid   = 30;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;     // knuckle diameter
knuckle_n   = 5;     // number of knuckles
knuckle_w   = plate_len / knuckle_n;  // segment width (8 mm)
knuckle_y   = plate_wid / 2;          // knuckle axis Y position (15)
knuckle_z   = plate_thk + 0.5;        // knuckle axis Z position (3)

// ---- Pin hole ----
pin_d       = 2.5;   // pin hole diameter

// ---- Cutting overlap ----
eps         = 0.5;   // extension past faces for clean cuts

// Knuckle centre X positions (1st, 3rd, 5th segments)
function knuckle_x(i) = (i - 1) * knuckle_w + knuckle_w / 2;

difference() {
    union() {
        // Plate, centred in X/Y, resting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders along X axis
        for (i = [0 : knuckle_n - 1])
            if ((i + 1) % 2 == 1)  // 1st, 3rd, 5th segments
                translate([knuckle_x(i + 1), knuckle_y, knuckle_z])
                    cylinder(d = knuckle_d, h = plate_len + 2 * eps, $fn = 96);
    }

    // Pin holes through every knuckle along the X axis
    for (i = [0 : knuckle_n - 1])
        if ((i + 1) % 2 == 1)
            translate([knuckle_x(i + 1), knuckle_y, knuckle_z])
                rotate([0, 90, 0])
                    cylinder(d = pin_d, h = plate_len + 2 * eps, $fn = 64);
}
