// Pin hinge leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 45;    // plate length along X
plate_wid   = 25;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;     // knuckle diameter (cylinder along X)
knuckle_y   = 12.5;  // knuckle axis Y position
knuckle_z   = 3;     // knuckle axis Z position
knuckle_n   = 3;     // number of knuckles, evenly spaced along X
