pin_d       = 2.5;   // pin hole diameter

// ---- Cutting overlap ----
eps         = 0.5;   // extension past cut faces

module knuckle() {
    difference() {
        translate([0, knuckle_y, knuckle_z])
            cylinder(d = knuckle_d, h = plate_len + 2*eps, $fn = 96);
        // pin hole along X through the knuckle
        translate([-eps, knuckle_y, knuckle_z])
            cylinder(d = pin_d, h = plate_len + 2*eps, $fn = 64);
    }
}

union() {
    // Plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles on 1st and 3rd segments
    for (i = [0, knuckle_n - 1])
        translate([i * knuckle_pitch - knuckle_d/2, 0, 0])
            knuckle();
}
