```openscad
// Star-shaped indexing wheel
// Units: mm

$fn = 64;

// ---- Parameters ----
n_points      = 5;    // number of star points
outer_r       = 35;   // radius of outer (tip) points
inner_r       = 21;   // radius of inner (valley) points
plate_thick   = 4;    // plate thickness (Z)
hole_d        = 6;    // centre through-hole diameter
cut_extra     = 0.5;  // extra length for cutting shapes past faces

// ---- Star outline points ----
// Alternate outer/inner, first outer point on +X axis
star_pts = [
    for (i = [0 : 2 * n_points - 1])
        let (r = (i % 2 == 0) ? outer_r : inner_r,
             a = i * 180 / n_points)
        [r * cos(a), r * sin(a)]
];

// ---- Model ----
difference() {
    linear_extrude(height = plate_thick)
