// Tapered riser block for beaker - solid square frustum with a square pocket in the top face
// Print orientation: base on the bed (z = 0), top face at z = 20, centred on origin in X and Y

// ---------------- Parameters ----------------
bottom_size   = 80;   // length of the bottom square side (mm)
top_size      = 40;   // length of the top square side (mm)
height        = 20;   // height of the frustum (mm)
pocket_size   = 30;   // length of the square pocket side (mm)
pocket_depth  = 5;    // depth of the pocket cut into the top face (mm)
eps           = 0.5;  // overshoot for clean boolean cuts (mm)
$fn           = 64;   // curve resolution (not used here but set per rules)

// ---------------- Model ----------------
difference() {
    // Square frustum: hull of a bottom square and a top square, both centred
    hull() {
        translate([-bottom_size / 2, -bottom_size / 2, 0])
            cube([bottom_size, bottom_size, height]);

        translate([-top_size / 2, -top_size / 2, height])
            cube([top_size, top_size, height]);
    }

    // Square pocket, centred on the top face, open upward
    translate([-pocket_size / 2, -pocket_size / 2, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
```

