    for (sx = [-post_x, post_x])
        cylinder(d = post_d, h = post_h, center = true);

    // Straight bar on top, centred on origin
    translate([0, 0, post_h])
        cube([bar_len, bar_w, bar_t]);

    // Screw holes through each post from the bottom face
    for (sx = [-post_x, post_x])
        translate([sx, 0, -eps])
            cylinder(d = screw_d, h = screw_depth + 2 * eps);
}
