    translate([-total_length / 2 - eps, -gauge_width / 2 - eps, -eps])
        cube([total_length, gauge_width + 2 * eps, thickness + 2 * eps]);

    translate([-total_length / 2 - eps, 0, -eps])
        cube([total_length, eps, thickness + 2 * eps]);

    translate([-total_length / 2 - eps, gauge_width + eps, -eps])
        cube([total_length, eps, thickness + 2 * eps]);
