// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// --- Dimensions (mm) ---
thickness      = 4;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len  = 15;    // transition section length (X)

// Derived
grip_start_x   = -total_length/2 + grip_length;  // -52.5
gauge_start_x  = grip_start_x + grip_length;     // -27.5
transition_end_x = gauge_start_x + transition_len; // -12.5
right_transition_end = gauge_start_x + total_length - gauge_start_x - transition_len; // 12.5
right_gauge_start = right_transition_end + transition_len; // 27.5
right_grip_start = right_gauge_start + grip_length; // 52.5

// Width profile: grip -> transition -> gauge -> transition -> grip
function width(x) =
    x < right_transition_end ?
        x > transition_end_x ?
            gauge_width + (grip_width - gauge_width) * (transition_end_x - x) / transition_len :
            grip_width
        :
            gauge_width + (grip_width - gauge_width) * (x - gauge_start_x) / transition_len
    :
        x < right_grip_start ?
            gauge_width + (grip_width - gauge_width) * (right_gauge_start - x) / transition_len :
            grip_width;

difference() {
    translate([-total_length/2, -grip_width/2, 0])
        cube([total_length, grip_width, thickness]);

    // Cut out the central channel to leave the dog-bone shape
    translate([-right_gauge_start, -grip_width/2, -1])
        linear_extrude(thickness + 2)
            polygon([[-gauge_start_x, -grip_width/2],
                     [-gauge_start_x, grip_width/2],
                     [right_gauge_start, grip_width/2],
                     [right_gauge_start, -grip_width/2]]);
}
