    union() {
        // Left grip
        translate([grip_x0, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([x_mid - gauge_length/2, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right grip
        translate([x_mid + gauge_length/2 + transition_len, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            translate([x_mid + s * (gauge_length/2 + transition_len),
                       -grip_width/2, 0])
                linear_extrude(thickness)
                    polygon([[-transition_len, (grip_width - gauge_width)/2 * s],
                             [transition_len, (grip_width - gauge_width)/2 * s]]);
        }
    }

    // Cut a small notch along X at the gauge centre to avoid coplanar faces
    translate([x_mid - gauge_length/2 - 0.01, -gauge_width/2 - 0.01, 0])
        cube([gauge_length + 0.02, gauge_width + 0.02, thickness]);
