            cube([gauge_length, gauge_width, thickness]);

        // Right grip
        translate([x_mid + gauge_length/2 + transition_len, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            x1 = s > 0 ? x_mid - gauge_length/2 : grip_x0;
            x2 = x1 + transition_len;
            w1 = s > 0 ? gauge_width : grip_width;
            w2 = s > 0 ? grip_width : gauge_width;
            translate([x1, -w1/2, 0])
                linear_extrude([transition_len, thickness])
                    polygon([[0, -w2/2], [0, w2/2], [transition_len, -w1/2], [transition_len, w1/2]]);
