gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 10;    // transition section length (X)
eps            = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
gauge_x0 = -total_length/2 + grip_length + transition_len;  // gauge start X
// width at transition end (must match grip and gauge)
w_at_trans_end = grip_width - (grip_width - gauge_width) * transition_len / (grip_length + transition_len);

// ---------- Model ----------
difference() {
    union() {
        // End grips
        translate([-total_length/2, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        translate([total_length/2 - grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([gauge_x0, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            x1 = s > 0 ? total_length/2 - grip_length : -total_length/2 + grip_length;
            x2 = x1 + transition_len;
            w1 = grip_width;
            w2 = w_at_trans_end;
            translate([x1, -w1/2, 0])
                linear_extrude([thickness, 0])
                    polygon([[-transition_len/2, 0], [transition_len/2, 0],
                             [transition_len/2, w2 - w1], [-transition_len/2, w2 - w1]]);
        }
    }

    // Cutters, extended past faces
    translate([-total_length/2 - eps, -grip_width/2 - eps, -eps])
        cube([total_length + 2*eps, grip_width + 2*eps, thickness + 2*eps]);
    translate([total_length/2 - grip_length - eps, -grip_width/2 - eps, -eps])
        cube([grip_length + 2*eps, grip_width + 2*eps, thickness + 2*eps]);
    translate([gauge_x0 - eps, -gauge_width/2 - eps, -eps])
        cube([gauge_length + 2*eps, gauge_width + 2*eps, thickness + 2*eps]);
}
