// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 6;     // gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // transition section length (X)

// Derived
grip_area     = grip_width * grip_length * 2;  // both grip end blocks
transition_x0 = -total_length / 2 + grip_length + transition_len;  // start of first transition
transition_x1 = transition_x0 + transition_len * 2;                  // end of second transition

// ---------- Model ----------
difference() {
    // Outer shape: two grip end blocks + two linear transitions + central gauge
    union() {
        // Grip end blocks
        translate([-total_length / 2, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        translate([total_length / 2 - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Transition sections (width changes linearly from grip to gauge)
        for (x = [transition_x0, transition_x1])
            translate([x, -grip_width / 2, 0])
                linear_extrude(thickness)
                    polygon([[-transition_len, -grip_width / 2],
                             [-transition_len, grip_width / 2],
                             [transition_len, grip_width / 2],
                             [transition_len, -grip_width / 2]]);

        // Gauge section
        translate([transition_x1 - transition_len, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);
    }

    // Central through-hole (reduces stress concentration)
    translate([0, 0, -1])
        cylinder(d = gauge_width * 0.5, h = thickness + 2, $fn = 64);
}
