// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// --- Dimensions (mm) ---
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len  = 15;    // transition section length (X)

// Derived
grip_start_x   = -total_length/2 + grip_length;  // -52.5
gauge_start_x  = grip_start_x + grip_length;     // -27.5
transition_end_x = gauge_start_x + transition_len; // -12.5

module specimen() {
    difference() {
        // Outer shape: grip -> transition -> gauge -> transition -> grip
        union() {
            for (sx = [-grip_start_x, grip_start_x])
                translate([sx, 0, 0])
                    cube([grip_length, grip_width, thickness]);
            for (tx = [-transition_end_x, transition_end_x])
                translate([tx, 0, 0])
                    cube([transition_len, grip_width - (grip_width - gauge_width) * (transition_len - (tx - transition_end_x)) / transition_len, thickness]);
            translate([gauge_start_x, 0, 0])
                cube([gauge_length, gauge_width, thickness]);
        }
        // Central hole along X, through thickness
        translate([0, 0, -1])
            cylinder(d = gauge_width / 2, h = thickness + 2);
    }
}

specimen();
