// ---- Derived ----
rim_or  = rim_od / 2;
rim_ir  = rim_or - rim_width;
hub_r   = hub_d / 2;
spoke_start = hub_r - eps;   // spokes overlap into hub
spoke_end   = rim_ir + eps;  // spokes overlap into rim

difference() {
    union() {
        // Rim
        difference() {
            cylinder(h = wheel_thk, r = rim_or);
            translate([0, 0, -eps])
                cylinder(h = wheel_thk + 2 * eps, r = rim_ir);
        }

        // Hub
        cylinder(h = wheel_thk, r = hub_r);

        // Spokes, first along +X
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([spoke_start, -spoke_width / 2, 0])
                    cube([spoke_end - spoke_start, spoke_width, wheel_thk]);
    }

    // Axle hole
    translate([0, 0, -eps])
        cylinder(h = wheel_thk + 2 * eps, d = axle_d);
