rim_w       = 5;     // rim width (radial)
hub_d       = 20;    // hub diameter
axle_d      = 5;     // central axle hole diameter
spoke_w     = 4;     // spoke width (radial)
spoke_count = 6;     // number of spokes
first_angle = 0;     // first spoke along +X axis (degrees)

eps         = 0.5;   // cutter overshoot past faces
$fn         = 128;   // curve resolution

// ---------- Derived ----------
rim_i = outer_d - 2 * rim_w;   // inner diameter of rim (ring width)
r     = outer_d / 2;           // outer radius

