difference() {
    union() {
        // Outer rim (ring)
        cylinder(d = outer_d, h = part_t);

        // Hub
        cylinder(d = hub_d, h = part_t);

        // Spokes, evenly spaced
        for (i = [0 : spoke_count - 1]) {
            a = first_angle + i * 360 / spoke_count;
            translate([r * cos(a), r * sin(a), 0])
                cube([spoke_w, r, part_t]);
        }
    }

    // Cut through the hub: axle hole + clearance
    translate([0, 0, -eps])
        cylinder(d = axle_d + 2 * eps, h = part_t + 2 * eps);
