// Flat dial ring with radial tick marks for a rotary stage
// Units: mm. Prints flat on the bed, centred on origin.

// ---- Ring dimensions ----
outer_d     = 50;    // outer diameter
inner_d     = 30;    // inner diameter (bore)
thickness   = 3;     // ring thickness (Z)

// ---- Tick mark dimensions ----
tick_count  = 36;    // number of evenly spaced ticks (10 deg apart)
tick_width  = 1.5;   // groove width (tangential)
tick_depth  = 1.5;   // groove depth into top face
tick_length = 3;     // radial length, measured inward from outer edge
tick_start_angle = 0; // first tick on +X axis

// ---- Cutting overlap ----
eps = 0.5;           // extension of cutters past faces

$fn = 128;

outer_r = outer_d / 2;
inner_r = inner_d / 2;

difference() {
    // Annulus
    difference() {
        cylinder(h = thickness, r = outer_r);
        translate([0, 0, -eps])
            cylinder(h = thickness + 2 * eps, r = inner_r);
    }

    // Radial tick grooves in the top face
    for (i = [0 : tick_count - 1]) {
        rotate([0, 0, tick_start_angle + i * 360 / tick_count])
            translate([outer_r - tick_length,
                       -tick_width / 2,
                       thickness - tick_depth])
                cube([tick_length + eps, tick_width, tick_depth + eps]);
    }
}
