// Powder measuring scoop - hollow spherical bowl with flat handle
// Print orientation: bowl bottom on bed (z = 0), handle extending along +X

// ---------- Parameters ----------
bowl_outer_radius   = 10;   // outer radius of spherical bowl
wall_thickness      = 2;    // wall thickness of bowl
bowl_centre         = [0, 0, 10]; // centre of sphere (lower half kept)
handle_width        = 12;   // handle width along Y
handle_thickness    = 3;    // handle thickness along Z
handle_start_x      = 8;    // handle start position along X
handle_end_x        = 90;   // handle end position along X
cut_extra           = 0.5;  // overshoot for clean boolean cuts
$fn                 = 96;   // curve resolution

// ---------- Derived ----------
bowl_inner_radius = bowl_outer_radius - wall_thickness;
handle_top_z      = bowl_centre[2] - wall_thickness; // flush with rim (z = 7..10)

// ---------- Model ----------
union() {
    // Hollow bowl: lower half of spherical shell
    difference() {
        sphere(r = bowl_outer_radius, d = 20, $fn = $fn);
        translate([0, 0, -cut_extra])
            sphere(r = bowl_inner_radius, d = 16, $fn = $fn);
    }
    keep(z = [0, bowl_centre[2]]); // keep lower half, cut at equator

    // Flat handle, top face flush with rim
    translate([handle_start_x, -handle_width / 2, handle_top_z])
        cube([handle_end_x - handle_start_x, handle_width, handle_thickness]);
}
