// Print orientation: bowl bottom on bed (z = 0), handle extending along +X

// ---------- Parameters ----------
bowl_r      = 12;    // outer radius of spherical bowl
wall        = 1.5;   // wall thickness of bowl
bowl_z      = 12;    // z of sphere centre (rim at z = bowl_z, bottom at z = 0)
handle_w    = 8;     // handle width (Y)
handle_t    = 4;     // handle thickness (Z)
handle_x0   = 10.5;  // handle start (X)
handle_x1   = 92;    // handle end (X)
eps         = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---------- Model ----------
difference() {
    union() {
        // Bowl: lower half of a hollow sphere
        translate([0, 0, bowl_z])
            cylinder(r = bowl_r, h = bowl_z + 0.01, $fn = 128);   // outer
        translate([0, 0, bowl_z])
            cylinder(r = bowl_r - wall, h = bowl_z + 0.01, $fn = 128); // inner

        // Handle: flat plate, top face flush with rim (z = 8..12)
        translate([handle_x0, -handle_w / 2, bowl_z - handle_t])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }

    // Cut the solid below z = 0.01 so it rests on the bed
    translate([handle_x0 - 1, -handle_w / 2 - 1, 0])
        cube([handle_x1 - handle_x0 + 2, handle_w + 2, 0.01]);
}
```

