$fn = 96;

// ---------------- Parameters ----------------
bowl_outer_r   = 12;     // outer radius of the hemispherical bowl
bowl_wall      = 1.5;    // bowl wall thickness
bowl_inner_r   = bowl_outer_r - bowl_wall; // inner (cavity) radius = 10.5
