// Powder measuring scoop - hollow spherical bowl with flat handle
// Units: mm. Print orientation: bowl bottom on bed (z = 0), handle along +X.

// ---------- Parameters ----------
bowl_outer_radius   = 12;    // outer radius of spherical bowl
bowl_wall_thickness = 1.5;   // thickness of bowl wall
bowl_centre         = [0, 0, 12]; // sphere centre (lower half kept)
handle_width        = 8;     // handle width (Y)
handle_thickness    = 4;     // handle thickness (Z), top face flush with rim
handle_x_start      = 10.5;  // handle start (X), above rim
handle_x_end        = 92;    // handle end (X)
cut_extra           = 0.5;   // overshoot for cutting shapes past faces
$fn                 = 96;    // curve resolution

// ---------- Derived ----------
bowl_inner_radius = bowl_outer_radius - bowl_wall_thickness; // 10.5
handle_z_top      = bowl_centre[2] - bowl_wall_thickness;    // z = 8 (rim)

// ---------- Model ----------
union() {
    // Hollow spherical bowl (lower half)
    difference() {
        sphere(r = bowl_outer_radius, center = bowl_centre);
        translate([0, 0, -cut_extra])
            sphere(r = bowl_inner_radius, center = [0, 0, bowl_centre[2] + cut_extra]);
    }

    // Flat handle, centred on y = 0, running along +X
    translate([handle_x_start, -handle_width / 2, handle_z_top])
        cube([handle_x_end - handle_x_start, handle_width, handle_thickness]);
}
