// Powder measuring scoop - hollow spherical bowl with flat handle
// Units: mm. Print orientation: bowl bottom on bed (z = 0), handle along +X.

// ---------- Parameters ----------
bowl_outer_radius   = 10;    // outer radius of spherical bowl
bowl_wall_thickness = 1.5;   // thickness of bowl wall
bowl_centre         = [0, 0, 10]; // sphere centre (lower half kept)
handle_width        = 10;    // handle width (Y)
handle_thickness    = 3;     // handle thickness (Z)
handle_x_start      = 8.5;   // handle start (X), above rim
handle_x_end        = 90;    // handle end (X)
cut_extra           = 0.5;   // overshoot for clean boolean cuts
$fn                 = 96;    // facet count for curved surfaces

// Derived
bowl_inner_radius = bowl_outer_radius - bowl_wall_thickness;
handle_top_z      = bowl_centre[2] - bowl_wall_thickness; // flush with rim

// ---------- Model ----------
union() {
    // Hollow spherical bowl (lower half)
    difference() {
        sphere(r = bowl_outer_radius, d = 20, $fn = $fn);
        translate([0, 0, -cut_extra])
            sphere(r = bowl_inner_radius, d = 17, $fn = $fn);
    }
    keep(z = [0, handle_top_z]); // keep lower half, rim at z = 10

    // Flat handle, centred on y = 0, top face flush with rim
    translate([handle_x_start, -handle_width / 2, handle_top_z])
        cube([handle_x_end - handle_x_start, handle_width, handle_thickness]);
}
