// Ring weight for flask in water bath
// Print orientation: flat on bed, z = 0 up to z = height

// ---- Dimensions (mm) ----
cross_d      = 8;     // cross-section diameter
ring_r       = 25;    // centre circle radius
height       = 4;     // middle plane height (z)
eps          = 0.5;   // cutter overshoot
$fn          = 128;   // curve resolution

// Derived
R = ring_r + cross_d / 2;  // outer radius
r = ring_r - cross_d / 2;  // inner radius

difference() {
    // Solid torus centred on z = height
    translate([0, 0, height])
        cylinder(r = R, r2 = r, h = 2 * height, $fn = 256);

    // Cut out the bottom half so the ring rests on z = 0
    translate([0, 0, -eps])
        cylinder(r = R, r2 = r, h = height + 2 * eps, $fn = 256);
}
