// Pin hinge leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 40;    // plate length along X (mm)
plate_wid   = 25;    // plate width along Y (mm)
plate_thk   = 3;     // plate thickness along Z (mm)

knuckle_d   = 7;     // knuckle cylinder diameter (mm)
knuckle_z   = 3.5;   // knuckle axis height above bed (mm)
knuckle_y   = 12.5;  // knuckle axis Y position (mm)
knuckle_n   = 5;     // number of knuckle segments
knuckle_h   = plate_len / knuckle_n;  // segment length along X (mm)

pin_d       = 2;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the +Y edge: cylinders whose axis runs along X
        for (i = [0 : knuckle_n - 1]) {
            x_c = (i - (knuckle_n - 1)/2) * knuckle_h;
            translate([x_c, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = knuckle_h + 2*eps, $fn = $fn);
        }
    }

    // Pin holes through every knuckle along the common X axis
    for (i = [0 : knuckle_n - 1]) {
        x_c = (i - (knuckle_n - 1)/2) * knuckle_h;
        translate([x_c, knuckle_y, knuckle_z])
            cylinder(d = pin_d, h = knuckle_h + 2*eps, $fn = $fn);
    }
}
```

