    [knuckle_pitch, knuckle_y, knuckle_z],
    [3 * knuckle_pitch, knuckle_y, knuckle_z],
    [5 * knuckle_pitch, knuckle_y, knuckle_z]
];

difference() {
    union() {
        // Plate, centred in X/Y, resting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders along X axis
        for (c = knuckle_c)
            translate(c)
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = plate_len + 2 * eps, center = true);
    }

    // Pin holes along X axis through every knuckle
    for (c = knuckle_c)
        translate(c)
            rotate([0, 90, 0])
                cylinder(d = knuckle_hole_d, h = plate_len + 2 * eps, center = true);
}
