// Pin hinge leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 60;    // plate length along X (mm)
plate_wid   = 30;    // plate width along Y (mm)
plate_thk   = 2.5;   // plate thickness along Z (mm)

knuckle_d   = 6;     // knuckle cylinder diameter (mm)
knuckle_z   = 3;     // knuckle axis height above bed (mm)
knuckle_y   = 15;    // knuckle axis Y position (mm)
knuckle_n   = 5;     // number of knuckle segments
knuckle_step = plate_len / knuckle_n; // segment length (12 mm)

pin_d       = 3;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments
        for (i = [0 : knuckle_n - 1]) {
            if (i % 2 == 0) { // 0, 2, 4 -> 1st, 3rd, 5th segments
                translate([-knuckle_step/2 + i*knuckle_step, knuckle_y, knuckle_z])
                    cylinder(d = knuckle_d, h = plate_thk + 2*eps, center = true);
