    // Pin holes along X through every knuckle
    for (i = [0 : knuckle_n - 1]) {
        if (i % 2 == 0) {
            translate([-knuckle_step/2 + i*knuckle_step, knuckle_y, knuckle_z])
                translate([-knuckle_step/2, -plate_wid/2, -eps])
                    cube([knuckle_step, plate_wid + 2*eps, plate_thk + 2*eps]);
