// Star-shaped indexing wheel
// 8-pointed star plate with a central through-hole

$fn = 96;

// ---- Parameters ----
n_points   = 8;     // number of star points
r_outer    = 35;    // radius to outer (tip) points
r_inner    = 21;    // radius to inner (valley) points
thickness  = 5;     // plate thickness (Z)
hole_d     = 8;     // central through-hole diameter
eps        = 0.5;   // cutter overshoot past faces

// ---- Star outline points ----
// Alternating outer/inner vertices, first outer point on +X axis
star_pts = [
    for (i = [0 : 2 * n_points - 1])
        let (
            a = i * 180 / n_points,
            r = (i % 2 == 0) ? r_outer : r_inner
        )
        [r * cos(a), r * sin(a)]
];

// ---- Model ----
difference() {
    // Star plate
    linear_extrude(height = thickness)
        polygon(points = star_pts);

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
}
