// Cabinet door pull handle
// Print orientation: posts on the bed (z = 0), bar on top (z = 20..28)

$fn = 64;

// ---- Posts ----
post_d       = 10;    // post diameter
post_h       = 20;    // post height (z = 0 to 20)
post_x       = 32;    // post axis offset from origin in X (+/-)

// ---- Bar ----
bar_l        = 74;    // bar length (X)
bar_w        = 10;    // bar width (Y)
bar_t        = 8;     // bar thickness (Z), z = 20 to 28

// ---- Screw holes ----
hole_d       = 4.5;   // screw hole diameter
hole_depth   = 12;    // screw hole depth from bottom face

// ---- Misc ----
eps          = 0.5;   // cutter overshoot past faces
overlap      = 0.01;  // small overlap so posts fuse with bar

difference() {
    union() {
        // Posts
        for (sx = [-1, 1])
            translate([sx * post_x, 0, 0])
                cylinder(d = post_d, h = post_h + overlap);

        // Bar
        translate([-bar_l / 2, -bar_w / 2, post_h])
