gauge_end_x    = gauge_start_x + gauge_length;   // 20
grip_end_x     = gauge_end_x + transition_len;   // 35
right_grip_x   = grip_end_x + grip_length;       // 65

// Check: -65 to 65 = 130 mm total

module width(x) {
    // Linear width change in transition zones
    if (x <= grip_start_x || x >= right_grip_x)
        return grip_width;
    if (x < gauge_start_x)
        return grip_width + (gauge_width - grip_width) * (x - grip_start_x) / transition_len;
    if (x > gauge_end_x)
        return grip_width + (gauge_width - grip_width) * (right_grip_x - x) / transition_len;
    return gauge_width;
}

difference() {
    translate([-total_length/2, -thickness/2, 0])
        linear_extrude(thickness)
            polygon([[-total_length/2, 0], [right_grip_x, 0]]); // base outline

    // Central cutout to form gauge section
    translate([gauge_start_x - 1, -gauge_width/2 - 1, 0])
        linear_extrude(thickness + 2)
            rectangle([gauge_length, gauge_width]);
}
