```openscad
// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// --- Dimensions (mm) ---
thickness      = 3;     // specimen thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len  = 10;    // transition section length (X)

// Derived
grip_start_x   = -total_length/2 + grip_length;  // -42.5
gauge_start_x  = grip_start_x + grip_length;     // -7.5
transition_end_x = gauge_start_x + transition_len; // 17.5

module specimen() {
    difference() {
        // Outer shape: grip -> transition -> gauge -> transition -> grip
        union() {
            // Left grip
            translate([-total_length/2, -grip_width/2, 0])
                cube([grip_length, grip_width, thickness]);
            // Right grip
            translate([total_length/2 - grip_length, -grip_width/2, 0])
                cube([grip_length, grip_width, thickness]);
            // Gauge
            translate([gauge_start_x, -gauge_width/2, 0])
                cube([gauge_length, gauge_width, thickness]);
            // Transitions (width changes linearly from grip to gauge)
            for (s = [-1, 1]) {
                x0 = s > 0 ? gauge_start_x : grip_start_x;
                x1 = x0 + transition_len;
                w0 = s > 0 ? grip_width : grip_width;
                w1 = s > 0 ? gauge_width : gauge_width;
                translate([x0, -w0/2, 0])
                    linear_extrude(thickness)
                        polygon([[-transition_len, w0 - w1], [0, w1 - w0]]);
            }
        }
        // Central cutout (keeps the part hollow and flexible)
        translate([0, -gauge_width/2 - 2, 0])
            cube([gauge_length, gauge_width + 4, thickness]);
    }
}

specimen();
