        translate([head_end - transition_len, -grip_width / 2, 0])
            linear_extrude(thickness)
                polygon([[gauge_x0 - transition_len, gauge_width / 2],
                         [gauge_x0 - transition_len, -gauge_width / 2],
                         [head_end - grip_length, -grip_width / 2],
                         [head_end - grip_length, grip_width / 2]]);
    }

    // Central gauge section, cut through
    translate([gauge_x0, -gauge_width / 2, -eps])
        cube([gauge_length, gauge_width, thickness + 2 * eps]);
}
