// Stiffened cover panel: flat plate with 5 longitudinal ribs
// Units: mm. Print orientation: plate flat on bed, ribs pointing up (+Z).

// ---------------- Parameters ----------------
plate_len   = 120;   // plate length along X
plate_wid   = 80;    // plate width along Y
plate_thk   = 2;     // plate thickness (z = 0 to 2)

rib_thk     = 3;     // rib thickness along X
rib_h       = 4;     // rib height above plate (z = 2 to 6)
rib_count   = 5;     // number of ribs
rib_pitch   = 20;    // centre-to-centre spacing of ribs along X
rib_overlap = 0.01;  // small overlap so ribs fuse into the plate

$fn = 64;

// ---------------- Derived ----------------
// Outer ribs are 20 mm from the plate ends, so the first rib centre is at
// x = 20 + rib_pitch/2 = 21 mm, and the last at x = 120 - 21 = 99 mm.
// This places the 5 ribs at x = 21, 41, 61, 81, 101 (20 mm apart).
rib_x_start = plate_len/2 - rib_overlap - rib_pitch * (rib_count - 1)/2;

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running the full width along Y, fused into the plate
    for (i = [0 : rib_count - 1]) {
        translate([rib_x_start + i * rib_pitch - rib_thk/2,
                   -rib_thk/2,
                   plate_thk])
            cube([rib_thk, rib_thk, rib_h]);
    }
}
