            cylinder(r = bowl_r - wall, h = bowl_z + eps);

        // Handle: flat plate, top face flush with rim (z = 8 to 12)
        translate([handle_x0, -handle_w / 2, bowl_z - handle_t])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
