cut_extra   = 0.5;   // extra length so cuts pass through faces

module knuckle(i) {
    translate([-plate_len/2 + i*seg_len, axis_y, axis_z])
        rotate([0, 90, 0])
            cylinder(d = knuckle_d, h = seg_len);
}

difference() {
    union() {
        // Flat plate, centred on origin in X and Y
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on alternate segments
        for (i = knuckle_segs) knuckle(i);
    }

    // Pin hole along the hinge axis through all knuckles
    translate([-plate_len/2 - cut_extra, axis_y, axis_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*cut_extra);
