    // Pin holes
    for (i = [0 : knuckle_n - 1])
        if ((i + 1) % 2 == 1)
            translate([knuckle_x(i) - knuckle_h / 2 - eps, knuckle_y, knuckle_z])
                cylinder(d = pin_d, h = knuckle_h + 2 * eps, $fn = 64);
