```openscad
// Star-shaped indexing wheel
// Units: mm

n_points   = 6;    // number of star points
r_outer    = 40;   // radius to outer (tip) points
r_inner    = 24;   // radius to inner (valley) points
thickness  = 4;    // plate thickness
hole_d     = 6;    // centre hole diameter
eps        = 0.5;  // cutter overshoot past faces

$fn = 96;

// Star outline: alternating outer/inner vertices, first outer point on +X
function star_pts(n, ro, ri) =
    [ for (i = [0 : 2*n - 1])
        let (a = i * 180 / n, r = (i % 2 == 0) ? ro : ri)
        [ r * cos(a), r * sin(a) ] ];

difference() {
    linear_extrude(height = thickness)
