// Tapered riser block for beaker - solid square frustum with a small square pocket in the top face
// Units: mm. Print orientation: base on bed (z = 0), top face at z = 30.

$fn = 64;

// ---- Frustum dimensions ----
bottom_size   = 60;   // bottom square side (X and Y)
top_size      = 20;   // top square side (X and Y)
height        = 30;   // frustum height (z = 0 to z = 30)

// ---- Pocket dimensions ----
pocket_size   = 10;   // square pocket side (X and Y)
pocket_depth  = 5;    // square pocket depth from top face

// ---- Cutting overlap ----
eps           = 0.5;  // extension of cutters past faces to avoid coplanar surfaces

// Derived: slope thickness change per mm in Z
slope = (bottom_size - top_size) / (2 * height);

module frustum() {
    // Linearly varying square: side(z) = top_size + 2 * slope * (z - 0)
    // (z = 0 gives bottom_size, z = height gives top_size)
    linear_extrude(height)
        translate([-bottom_size / 2, -bottom_size / 2, 0])
            cube([bottom_size, bottom_size, 1]);
}

module pocket() {
    translate([0, 0, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}

difference() {
    frustum();
    pocket();
}
