// ---------- Parameters ----------
post_d        = 10;    // post diameter
post_h        = 20;    // post height (z = 0 to 20)
post_x        = 32;    // post centre offset from origin in X (both posts at x = +/-32)
bar_len       = 74;    // bar length along X
bar_w         = 10;    // bar width along Y
bar_t         = 8;     // bar thickness (z = 20 to 28)
screw_d       = 3.4;   // screw hole diameter
screw_depth   = 12;    // screw hole depth from bottom face of posts
eps           = 0.5;   // cutter overshoot past faces
$fn           = 64;    // curve resolution

// ---------- Model ----------
union() {
    // Two round posts
    for (sx = [-post_x, post_x]) {
        cylinder(d = post_d, h = post_h, center = true);
        // Screw hole, extended past bottom and top faces
        translate([0, 0, -eps])
            cylinder(d = screw_d, h = screw_depth + post_h + 2 * eps);
    }

    // Straight bar, centred on origin, resting on the posts
    translate([-bar_len / 2, -bar_w / 2, post_h])
        cube([bar_len, bar_w, bar_t]);
}
