    translate([-total_length/2, -thickness/2, 0])
        cube([total_length, thickness, thickness]);

    // Grip cutouts (through the thickness)
    for (i = [0 : grip_count - 1]) {
        x0 = -total_length/2 + grip_length + i * (gauge_length + 2 * transition_len);
        translate([x0, -grip_width/2, -cut_extra])
            cube([grip_length, grip_width, thickness + 2 * cut_extra]);
    }

    // Transition cutouts, width changes linearly from grip to gauge
    for (i = [0 : grip_count - 1]) {
        x0 = -total_length/2 + grip_length + i * (gauge_length + 2 * transition_len);
        w1 = grip_width;
        w2 = gauge_width + (grip_width - gauge_width) * transition_len / (gauge_length + transition_len);
        translate([x0, -w1/2, -cut_extra])
            linear_extrude([transition_len, w1 + w2, thickness + 2 * cut_extra])
                polygon([[0, -w1/2], [transition_len, -w2/2], [transition_len, w2/2], [0, w1/2]]);
    }
}
