    translate([-total_length / 2, -thickness / 2, 0])
        cube([total_length, thickness, thickness]);

    for (s = [-1, 1])
        translate([s * head_start, -thickness / 2 - eps, 0])
            cube([grip_length + transition_len + eps, thickness + 2 * eps, thickness]);
