gauge_start_x  = grip_start_x + grip_length;     // -12.5
transition_end_x = gauge_start_x + transition_len; // -2.5

module specimen() {
    linear_extrude(thickness)
        union() {
            // Left grip
            translate([-total_length/2, -grip_width/2, 0])
                cube([grip_length, grip_width, thickness]);
            // Right grip
            translate([total_length/2 - grip_length, -grip_width/2, 0])
                cube([grip_length, grip_width, thickness]);
            // Gauge section
            translate([gauge_start_x, -gauge_width/2, 0])
                cube([gauge_length, gauge_width, thickness]);
            // Transitions (width changes linearly from grip to gauge)
            for (side = [-1, 1]) {
                x0 = side < 0 ? grip_start_x : transition_end_x;
                x1 = side < 0 ? gauge_start_x : gauge_start_x + transition_len;
                w0 = grip_width;
                w1 = gauge_width;
                translate([x0, -w0/2, 0])
                    linear_extrude(thickness)
                        polygon([x0, x1], [w0, w1]);
            }
        }
}

specimen();
