    // Cut out the two end grip regions, leaving the gauge and transitions
    for (i = [0 : grip_count - 1]) {
        x0 = -total_length / 2 + grip_length + transition_len + i * (grip_length + transition_len);
        translate([x0 - cutout, -grip_width / 2 - cutout, -cutout])
            cube([grip_length + 2 * cutout, grip_width + 2 * cutout, thickness + 2 * cutout]);
