    // Outer shape: two grip blocks with linearly tapered transitions
    union() {
        // Left grip
        translate([head_start - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Right grip
        translate([head_end, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (sx = [-1, 1])
            translate([sx > 0 ? gauge_x0 - transition_len : head_start - transition_len,
                       -grip_width / 2, 0])
                linear_extrude(thickness)
                    polygon([[-transition_len, -grip_width / 2],
                            [-transition_len, grip_width / 2],
