    // Gauge
    translate([gauge_x0, -gauge_width/2, 0])
        cube([gauge_length, gauge_width, thickness]);
}

difference() {
    shape();
    // Cut through the middle along X to check for solid
    translate([0, -1, 0])
        cube([total_length + 2, 2, thickness]);
