// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 4;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // transition section length (X)
cut_extra      = 0.5;   // cutter overshoot past end faces

$fn = 64;

// ---------- Derived ----------
w1 = grip_width;     // start width of transition
w2 = gauge_width;    // end width of transition
x0 = -total_length / 2;  // left end X position

// ---------- Model ----------
difference() {
    union() {
        // Left grip
        translate([x0, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge
        translate([x0 + grip_length - gauge_length, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right grip
        translate([x0 + grip_length + gauge_length + transition_len + grip_length,
                   -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Transitions (width changes linearly over transition_len)
        for (s = [-1, 1]) {
            translate([x0 + grip_length - transition_len + s * (transition_len + 1e-3),
                       -w1 / 2, 0])
                linear_extrude(thickness)
                    polygon([[-transition_len / 2, 0], [transition_len / 2, 0],
                             [transition_len / 2, s * (w1 - w2)],
                             [-transition_len / 2, s * (w1 - w2)]]);
        }
    }

    // Cutters, extended past end faces
    translate([x0 - cut_extra, -gauge_width / 2, 0])
        cube([cut_extra + grip_length + gauge_length + transition_len + grip_length + cut_extra,
               gauge_width, thickness]);

    translate([x0 + total_length - (cut_extra + grip_length + gauge_length + transition_len + grip_length + cut_extra),
               -gauge_width / 2, 0])
        cube([cut_extra + grip_length + gauge_length + transition_len + grip_length + cut_extra,
               gauge_width, thickness]);
}
