// ---------- Parameters ----------
outer_d      = 100;   // outer rim diameter
rim_w        = 6;     // rim width (radial)
hub_d        = 16;    // hub diameter
axle_d       = 6;     // central axle hole diameter
spoke_count  = 5;     // number of spokes
spoke_w      = 4;     // spoke width (radial)
part_t       = 5;     // part thickness (Z)
eps          = 0.5;   // cutter overshoot past faces

$fn = 128;

// ---------- Model ----------
difference() {
    // Outer rim (ring)
    cylinder(d = outer_d, h = part_t);

    // Central hub
    translate([0, 0, 0])
        cylinder(d = hub_d, h = part_t);

    // Axle hole through hub
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = part_t + 2 * eps);

    // Spokes, first along +X axis
    for (i = [0 : spoke_count - 1]) {
        a = i * 360 / spoke_count;
        translate([0, 0, 0])
            rotate([0, 0, a])
                linear_extrude(height = part_t)
                    polygon([[-spoke_w / 2, 0], [spoke_w / 2, 0],
                             [spoke_w / 2, hub_d / 2 - 1],
                             [-spoke_w / 2, hub_d / 2 - 1]]);
    }
}
